const spinnerLoad = (function() {

    var ajaxQueue = [];

    var operationId ="bulkAdd"

    function ajaxQueueRemove(operationId){
        var index = ajaxQueue.indexOf(operationId);
        if (index > -1) {
           ajaxQueue.splice(index, 1);
        }
    }

	function addSpinner(operationId) {
        ajaxQueue.push(operationId);
        $('#modal-spinner').show();
    }

    function removeSpinnerOnSuccess(operationId)  {
       ajaxQueueRemove(operationId);
       if (ajaxQueue.length == 0){
          $('#modal-spinner').hide();
       }
    }

    function removeSpinnerOnError(operationId)  {
       ajaxQueueRemove(operationId);
       if (ajaxQueue.length == 0){
          $('#modal-spinner').hide();
       }
    }
    function removeAllSpinnersOnError()  {
       console.error("unexpected error. removing spinner as fallback.")
       console.error(ajaxQueue);
       $('#modal-spinner').hide();
    }

    return {
        addSpinner: addSpinner,
        removeSpinnerOnSuccess: removeSpinnerOnSuccess,
        removeSpinnerOnError: removeSpinnerOnError,
        removeAllSpinnersOnError: removeAllSpinnersOnError
    };
})();

const utils = (function() {

	const currentBrandSeoName = $('#current-brand').data('brand-seoname');
	const currentRegion = $("meta[name='content-region']").attr('content');

	function decodeHtml(html) {
	    var txt = document.createElement("textarea");
	    txt.innerHTML = html;
	    return txt.value;
	}

	/**
	*This method returns the current base url for the site: /cnhistorefront/DSP/'brandCode'/
	**/
	function getCurrentBaseUrl(){
	    return basePath;
	}


	function getCurrentBaseUrlAdpated(regionCode, brandCode){
		let baseUrl = getCurrentBaseUrl();
		if(regionCode){
			baseUrl = baseUrl.replace('/' + currentRegion, '/' + regionCode);
		}
		baseUrl = baseUrl.replace(currentBrandSeoName, getSeoName(brandCode));
		return baseUrl;
	}

	function getSeoName(brandCode){
		return $('#dropdownBrandMenu').data('brand-'+ brandCode.toLowerCase());
	}

	function renderHtmlScript(data, container, callback, rawParams) {
    	var k = 0;
    	container.html("");
    	data.forEach(function (item) {
        	container.append(callback(item,k, rawParams));
        	k++;
		});
    	return k;
  	}

	function renderHtmlScriptNoParse(data, container, callback, callbackForNoResultsFound, typeSearch) {
		var k = 0;
		container.html("");
		if(data.length > 0) {
			data.forEach(function (products) {
				container.append(callback(products,k));
				k++;
			});
		} else {
			container.append(callbackForNoResultsFound(typeSearch));
		}
		return k;
	}

	function getCurrentSeoName(){
		return currentBrandSeoName;
	}

	function getUrlParameter(name) {
		var results = new RegExp('[\?&]' + name + '=([^&#]*)').exec(window.location.href);
		if (results == null) {
			return null;
		} else {
			return decodeURI(results[1]) || 0;
		}
	}

	function removeURLParameter(url, parameter) {
		var urlparts = url.split('?');
		if (urlparts.length >= 2) {
			var prefix = encodeURIComponent(parameter) + '=';
			var pars = urlparts[1].split(/[&;]/g);

			for (var i = pars.length; i-- > 0;) {
				if (pars[i].lastIndexOf(prefix, 0) !== -1) {
					pars.splice(i, 1);
				}
			}
			return urlparts[0] + (pars.length > 0 ? '?' + pars.join('&') : '');
		}
		return url;
	}

	function getCurrentRegion(){
		return currentRegion;
	}

	function escape(s) {
		return ('' + s)
			.replace(/\\/g, '\\\\')
			.replace(/\t/g, '\\t')
			.replace(/\n/g, '\\n')
			.replace(/\u00A0/g, '\\u00A0')
			.replace(/&/g, '\\x26')
			.replace(/'/g, '\\x27')
			.replace(/"/g, '\\x22')
			.replace(/</g, '\\x3C')
			.replace(/>/g, '\\x3E');
	}

	function escapeRegExp(string) {
		return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
	}

	return {
		decodeHtml:decodeHtml,
		getCurrentBaseUrl:getCurrentBaseUrl,
		getCurrentBaseUrlAdpated:getCurrentBaseUrlAdpated,
		renderHtmlScript:renderHtmlScript,
		renderHtmlScriptNoParse:renderHtmlScriptNoParse,
		getCurrentSeoName:getCurrentSeoName,
		getCurrentRegion:getCurrentRegion,
		getUrlParameter:getUrlParameter,
		removeURLParameter:removeURLParameter,
		escape: escape,
		escapeRegExp: escapeRegExp
	};
})();

