var productNumberId = 1;
const createQuickOrderProduct = function (product, rawParams) {
    var $template = $.parseHTML($('#quickOrderList').html());
    var stockIndicatorClass = "";
    var stockLevelIndicatorElement = $('.stock-indicator-quickOrder');
    var stockLevelIndicatorText = stockLevelIndicatorElement.attr('data-stock-' + product.stockLevelIndicator);
    var productPrice = product.price.value;
    var formattedPrice = product.price.formattedValue;
    var currency = $($template).find(".quick-order-product-price").data("currency");
    if (product.stockLevelIndicator === 'green') {
        stockIndicatorClass = "in-stock";
        $($template).find(".form-check-input").attr("data-select-all-child", true);
    } else if (product.stockLevelIndicator === 'yellow') {
        stockIndicatorClass = "on-limited-edition";
        $($template).find(".form-check-input").attr("data-select-all-child", true);
    } else {
        stockIndicatorClass = "not-in-stock";
        $($template).find(".form-check-input").attr("disabled", true);
        $($template).find(".form-check-input").attr("data-select-all-child", false);
        $($template).find(".quantity-add").attr("disabled", true);
        $($template).find(".quantity-remove").attr("disabled", true);
    }

    if (product.isSoldByMeasure) {
       $($template).find(".form-check-input").attr("disabled", true);
       $($template).find(".form-check-input").attr("data-select-all-child", false);
       $($template).find(".quantity-add").attr("disabled", true);
       $($template).find(".quantity-remove").attr("disabled", true);
    }

    if((product.stockLevelIndicator === 'green' || product.stockLevelIndicator === 'yellow') && !product.isSoldByMeasure)
    {
        $($template).find(".form-check-input").attr("checked", true);
        $('.quick-order-add-to-cart').removeClass('btn-primary-disabled');
        $('.quick-order-add-to-cart').prop('disabled', false);
    }

    var numberOfNotDisabledCheckbox = $($template).find(".form-check-input:not(:disabled)").length;
    var numberCheck = $($template).find(".form-check-input:checked").length;
    if(numberCheck === numberOfNotDisabledCheckbox && numberCheck > 0) {
        $(".quick_order_checkbox_select_all")
            .prop("disabled", false)
            .attr("checked", true);
    }

    var packQuantity = 1;
    if (product.isSoldAlwaysByPackage || (product.vendor != null && product.vendor.enablePackageQty && !product.isSoldAlwaysByUnit)) {
        if (product.packQuantity !== null) {
            packQuantity = parseInt(product.packQuantity);
            if (rawParams.template === "quick-order") {
                $($template).find(".quantity-number").val(product.packQuantity);
            } else if(rawParams.template === "quick-order-upload"){
                var newQty = packQuantity;
                $($template).find(".quantity-number").val(product.quantity);
            } else {
                var newQty = packQuantity * parseInt(product.quantity);
                $($template).find(".quantity-number").val(newQty);
            }
        }
    }
    $($template).find(".quantity-add").attr("id", productNumberId + "-quantity-counter");
    $($template).find(".quantity-remove").attr("id", productNumberId + "-quantity-counter");
    $($template).find(".quantity-number").attr("id", productNumberId + "-quantity-counter-quantity-number");
    $($template).find(".form-check-input").attr("id", product.code);
    $($template).find(".form-check-input").attr("onclick", "gtmSelectPlacement('" + product.code + "')");
    $($template).find(".form-check-input").attr("data-dealer-stock-quantity", product.dealerStockQuantity);
    $($template).find(".form-check-input").attr("data-subOwnership-stock", product.subOwnershipStockQuantity);
    $($template).find(".form-check-label").attr("for", product.code);
    $($template).attr("data-product-code", product.code);
    $($template).find("img").attr("src", product.thumbnail.url);
    $($template).find(".quantity-add").attr("data-product-id", product.code);
    $($template).find(".quantity-remove").attr("data-product-id", product.code);
    $($template).find(".quantity-number").attr("data-product-id", product.code);
    $($template).find(".quick-order-product-price").attr("data-product-id", product.code);
    $($template).find(".quick-order-product-code").text('#' + product.code);
    $($template).find(".quick-order-product-name").text(product.name);
    $($template).find(".js-notif-msgs").attr("data-product-code", product.code);
    $($template).find('ul[data-quick-order="list-desktop"]').attr("data-item-category", product.gtmProductData.itemCategory);
    $($template).find('ul[data-quick-order="list-desktop"]').attr("data-item-category2", product.gtmProductData.itemCategory2);

    if (product.stockLevelIndicator != 'red') {
        $($template).find(".quick-order-product-price").text(product.price.formattedValue);
        $($template).find(".quick-order-product-price").attr("data-product-price", product.price.value.toFixed(2));
    }
    if (product.isSoldByMeasure) {
        var noPrice = $($template).find(".quick-order-product-price").data("no-price");
        $($template).find(".quick-order-product-price").text(noPrice);
        $($template).find(".quick-order-product-price").attr("data-product-price", noPrice);
    }
    $($template).find(".delete-button").attr("onclick", "window.deleteProduct('" + product.code + "')");
    $($template).find(".status-text").text(stockLevelIndicatorText);
    $($template).find(".status-circle").attr("class", "status-circle " + stockIndicatorClass);
    productNumberId = productNumberId + 1;

    if (stockIndicatorClass !== 'not-in-stock') {
        $($template[1]).on("click", ".quantity-add", function () {
            quantityAdd(this);
        });
        $($template[1]).on("click", ".quantity-remove", function () {
            quantityRemove(this);
        });
    }
    function quantityAdd(target) {
        var counter;

        if (target.hasAttribute("id")) {
            var id = $(target).attr("id");
            counter = $("#" + id + "-quantity-number");
        } else {
            counter = $(".quantity-number");
        }
        for (var i = 0; i < counter.length; i++) {
            var n1 = parseInt($(counter[i]).val(), 10);
            var count = n1 + packQuantity;
            if (product.stock.stockLevel >= count) {
                $(counter[i]).empty().append(count);
                $(counter).val(count);
                productPrice = (product.price.value / packQuantity) * count;
                $('span[data-product-id="' + product.code + '"]').text(currency + productPrice.toFixed(2));

            }
        }
    }

    function quantityRemove(target) {
        var counter;

        if (target.hasAttribute("id")) {
            var id = $(target).attr("id");
            counter = $('#' + id + '-quantity-number');
        } else {
            counter = $('.quantity-number');
        }

        for (var i = 0; i < counter.length; i++) {
            var n2 = parseInt($(counter[i]).val(), 10);
            var subPrice = 1;
            if (packQuantity !== 1) {
                if (rawParams.template === "quick-order") {
                    $(counter[i]).empty().append(Math.max(packQuantity, n2 - packQuantity));
                    $(counter).val(Math.max(packQuantity, n2 - packQuantity));
                    subPrice = packQuantity;
                } else {
                    $(counter[i]).empty().append(Math.max(newQty, n2 - packQuantity));
                    $(counter).val(Math.max(newQty, n2 - packQuantity));
                    subPrice = newQty;
                }
            } else {
                $(counter[i]).empty().append(Math.max(1, n2 - 1));
                $(counter).val(Math.max(1, n2 - 1));
            }

           if (Number(productPrice.toFixed(2)) > Number(product.price.value.toFixed(2))) {
                productPrice = productPrice - product.price.value;
                $('span[data-product-id="' + product.code + '"]').text(currency + productPrice.toFixed(2));
            }
        }
    }

    return $template;
}

const createQuickOrderNewItem = function (product) {
    var $template = $.parseHTML($('#quick-order-not-existing-template').html());
    $($template).attr("id", product + "remove");
    $($template).find(".not-existing-button").attr("id", product);
    $($template).find(".form-control").attr("id", product);
    $($template).find(".form-control").val(product);
    $($template).find(".error-message").text($("#addNewItem").attr("data-error-message-exists"));

    return $template;
}

const createAssemblyItem = function (assembly,k,accordionNumber) {

    const isMobile = window.matchMedia('screen and (max-width: 767.98px)').matches;
    var $template = '';

    if(isMobile) {
        $template = $.parseHTML($('#category-assembly-template-mobile').html());
        $($template).find(".collasped-element__body__card-children__element").text(assembly.assemblyFullName);
        $($template).find(".collasped-element__body__card-children__element").attr("title",assembly.assemblyFullName);
        $($template).find(".collasped-element__body__card-children__element").attr("data-drawing-card","dc-"+ k);
        $($template).find(".collasped-element__body__card-children__element").attr("aria-label",assembly.assemblyFullName);
        $($template).find(".collasped-element__body__card-children__element").attr("data-model-id","dc-"+ k);
        $($template).find(".assembly-model-page-main-content__products-container-card-model").attr("data-model-id","dc-"+ k);
        $($template).find(".assembly-model-page-main-content__img-card").attr("src",assembly.urlAssemblyImage);
        $($template).attr("id","cl-" + accordionNumber + "-" + k);
        $('.assembly-page-toggle').find('input').each(function() {
            if($(this).hasClass('d-none')) {
                $('.assembly-page-toggle').parent().addClass('d-none');
            }
        });
        $($template).find(".assembly-model-page-main-content__products-container-card-model").on("click",function(e){
                bindCollapsedItem(e, isMobile);
                e.preventDefault();
                var $modelId = $(this).data("model-id");
                var url = $("#" + $modelId).attr('href');
                window.location.href = url;
            }
        );
    } else {
        $template = $.parseHTML($('#category-assembly-template').html());
        $($template).find(".collasped-element__body__card-children__element").text(assembly.assemblyFullName);
        $($template).find(".collasped-element__body__card-children__element").attr("title",assembly.assemblyFullName);
        $($template).find(".collasped-element__body__card-children__element").attr("data-drawing-card","dc-"+ k);
        $($template).find(".collasped-element__body__card-children__element").attr("data-model-id","dc-"+ k);
        $($template).attr("id","cl-" + accordionNumber + "-" + k);
        $($template).find(".collasped-element__body__card-children__element").on("click",function(e){
            var $modelId = $(e.target).data("model-id");
            if($(this).closest('li[data-model-id]').hasClass("text-brand-color"))
            {
                var url = $("#" + $modelId).attr('href');
                window.location.href = url;
            }
            else {
                $('.collasped-element__body__card-children').removeClass("text-brand-color");
                $(this).closest('li[data-model-id]').addClass("text-brand-color");
                bindCollapsedItem(e, isMobile);
            }

        });
    }

    return $template;
}

function bindCollapsedItem(event, isMobile) {
    var $sidebarModel = $('[data-model-id]');
    $sidebarModel.on("click", function (e) {
        var modelId = $(event.target).data("model-id");
        if (modelId) {
            $sidebarModel.removeClass('text-brand-color');
            $("a[id^='dc']").removeClass("assembly-model-page-main-content__products-container-card-model-active");
            $("a[id^='dc']").addClass("assembly-model-page-main-content__products-container-card-model");
            $(this).addClass("text-brand-color");
            let activeCard = "a[id^='" + modelId + "']";
            $(activeCard).addClass("assembly-model-page-main-content__products-container-card-model-active");

            if(!isMobile) {
                var targetElement = document.getElementById(modelId);
                if (targetElement) {
                var elementPosition = targetElement.getBoundingClientRect().top;
                var offsetPosition = elementPosition - window.innerHeight / 2 + targetElement.offsetHeight / 2;

                    $(".assembly-model-page-main-content__products-container").animate({
                    scrollTop: parseInt(elementPosition) - parseInt($(".assembly-model-page-main-content__products-container").offset().top) + $(".assembly-model-page-main-content__products-container").scrollTop()
                    }, 500);

                // Smoothly scroll to the calculated position
                    setTimeout(function() {
                    // Execute the scroll after the delay
                        window.scrollBy({
                        top: offsetPosition,
                        behavior: "smooth"
                        });
                    }, 1000);
                }
            }
        }
    });
}

const createAssemblyListImage = function (genericAssembly,k, rawParams) {
   if(!rawParams){
       return;
   }
   var modelIsTechTypeDriven = sessionStorage.getItem('modelIsTechnicalTypeDriven');
	var name;
	var $template = $(rawParams.template).clone();
	var serialNumberFilter = sessionStorage.getItem('serialNumberCode');
    var resourcePath = $("meta[name='resource-path']").attr("content")
	
	if (serialNumberFilter !== null && $('#serial-number-filter').is(":checked")){
		name = getAssemblyNameFiltered(genericAssembly);
	}
	else{
		name = genericAssembly.assemblyFullName;
	}
    var code = genericAssembly.assemblyCode;
	var flexDiv = $(".active.drawing-element__header__icons");
	flexClass = flexDiv.attr("id").replace("de-","");
	$($template).find(".img-assembly").attr("src",decodeHtml(genericAssembly.urlAssemblyImage + "&page=model")).attr("alt",name);
	$($template).find(".assembly-text").text(name);
	$($template).find(".assembly-text").attr("toggle", "tooltip")
	$($template).find(".assembly-text").attr("title", name)
	$($template).find(".assembly-text").attr("aria-label", name)
	$($template).addClass("flex-" + flexClass);
	$($template).attr("href",getAssemblyUrl(genericAssembly,null,rawParams.serialNumber,rawParams.isSnFilterEnabled));
	$($template).attr("id","dc-" + k);
	return $template;
}

/**
 * @param functionalGroupName if null consider current functional group
 */
function getAssemblyUrl(assembly, functionalGroupName,serialNumber,isSnFilterEnabled){
	let page =  $('#current-category-div').data('category-type')
	let url;
	if (page.toLowerCase() === 'model'){
		url = assemblyUrlBuilderModelPage(assembly,serialNumber,isSnFilterEnabled);
	}
	else {
		url = assemblyUrlBuilderAssemblyPage(assembly, functionalGroupName);
	}	
	
	return url;
}

function assemblyUrlBuilderModelPage(assembly,serialNumber,isSnFilterEnabled){
    const url = window.location.href;
    if(serialNumber != null && serialNumber != '' && isSnFilterEnabled != null)
    {
        return getCurrentBaseUrl() + assembly.assemblyUrl.substring(1) + "/" + assembly.modelCode + "?serial_number=" + serialNumber + "&isSnFilterEnabled=" + isSnFilterEnabled;
    }
   if(url.includes("modelSerialSearch=true"))
   {
      return getCurrentBaseUrl() + assembly.assemblyUrl.substring(1) + "/" + assembly.modelCode + "?modelSerialSearch=true";
   }
   return getCurrentBaseUrl() + assembly.assemblyUrl.substring(1) + "/" + assembly.modelCode;
}


function getSearchInModelSelector(selector){
	if($('#cnhi-expand-models').hasClass('triggered')){
		return selector + '-all-models';
	}
	else{
		return selector;
	}
}

