async function cartDataLayer(checkoutStep) {
    const cartListGTM = $("#gtm-cart-data").val();
    const cartList = parseGTMJsonData(cartListGTM).gtmCartList;
    const subtitle = $('.card.checkout-payment-method-card.selected').data("subtitle");
    const shippingType = $('.card.checkout-shipping-method-card.selected').data("delivery-name");
    const gtmGlobalData = parseGTMJsonData($("#gtmGlobalDataJson").html());

    if (!gtmGlobalData.euNaftaDataLayerEnabled) return;

    window.dataLayer = window.dataLayer || [];

    for (const cart of cartList) {
        if (!cart.cartId) continue;

        const value = parseFloat(cart.value).toFixed(2);
        const dealerCoupon = cart.couponName === null ? undefined : true;
        const items = [];

        for (const product of cart.gtmCartProducts) {
            const defaultValue = "Uncategorized products";
            const formattedDefaultValue = defaultValue.replace(/ /g, "_").toLowerCase();
            const price = parseFloat(product.productPrice).toFixed(2);
            const qty = parseInt(product.quantity, 10);

            // Prefer in-memory map (multi-carousel-safe) over localStorage fallbacks
            const _plm = window._productListMap && window._productListMap[product.itemId];
            const listCode =
                (_plm && _plm.item_list_id) ||
                localStorage.getItem(product.itemId + "_listCode") ||
                localStorage.getItem(product.itemId + "_plpListCode") ||
                localStorage.getItem(product.itemId + "_defaultlistCode") ||
                defaultValue;

            const listName =
                (_plm && _plm.item_list_name) ||
                localStorage.getItem(product.itemId + "_listName") ||
                localStorage.getItem(product.itemId + "_plpListName") ||
                localStorage.getItem(product.itemId + "_defaultlistName") ||
                formattedDefaultValue;

            items.push({
                item_id: product.itemId,
                item_name: `${gtmGlobalData.sessionBrand}|${product.itemName}`,
                affiliation: "My CNHI Store",
                currency: gtmGlobalData.storeCurrency,
                item_brand: gtmGlobalData.sessionBrand,
                item_category: product.itemCategory,
                item_category2: product.itemCategory2,
                item_list_id: listCode,
                item_list_name: listName,
                price: +price,
                quantity: qty,
            });
        }

        const shipping_tier = shippingType;
        const payment_type = subtitle;

        if (checkoutStep === "deliveryStep") {
            const ecommerceShipping = {
                currency: gtmGlobalData.storeCurrency,
                value: +value,
                shipping_tier,
                items,
            };

            if (dealerCoupon !== undefined) {
                ecommerceShipping.coupon = dealerCoupon;
            }

            window.dataLayer.push({
                event: "add_shipping_info",
                ecommerce: ecommerceShipping,
            });
        }

        if (checkoutStep === "payment") {
            const ecommercePayment = {
                currency: gtmGlobalData.storeCurrency,
                value: +value,
                payment_type,
                items,
            };

            if (dealerCoupon !== undefined) {
                ecommercePayment.coupon = dealerCoupon;
            }

            window.dataLayer.push({
                event: "add_payment_info",
                ecommerce: ecommercePayment,
            });
        }
    }
}

