async function addToCart(productStock, changeOfQuantity, productCodePost, event) {
    const isEuSite = $(".log").attr('data-isEuSite');
    const anonymous = $(".log").attr('data-anonymous');
    const token = $("meta[name='_csrf']").attr("content");

    if ((isEuSite == 'true') && (anonymous == 'true')) {
        $('#showModalLoginEu').modal('show');
        return;
    }

    latestAddToCart.type = "SINGLE";
    latestAddToCart.productCode = productCodePost;
    latestAddToCart.token = token;
    latestAddToCart.quantity = changeOfQuantity;
    if (typeof latestAddToCart.quantity === 'undefined') {
        latestAddToCart.quantity = 1;
    }

    return addToCartPost(latestAddToCart.productCode, latestAddToCart.quantity, latestAddToCart.token, undefined, undefined, event);
}

function addToCartPLP(type, $result, isMultipleParts, isAddSomeParts, fromPage) {
    if($result.length !== 0)
    {
        var cartEntries = [];
        var cartEntriesString = [];
        for (var i = 0, j = 0; i < $result.length; i++) {
            var res = $($result[i]);
            var productCode = res.data("product-code");
            var dealerStock = res.data("dealer-stock-quantity");
            var subOwnershipStock = res.data("subownership-stock");
            var inputType = res.data("input-type");
            var quantity = res.val() !== "" ? res.val() : res.data("quantity");
            var cartEntry;
            if (type === inputType) {
                cartEntry = { quantity: 0, product: { code: productCode }, dealerStock: dealerStock, subOwnershipStock: subOwnershipStock };
                if (quantity == undefined || quantity == "") {
                    cartEntry.quantity = 1;
                } else {
                    cartEntry.quantity += parseInt(quantity);
                }
                cartEntries[j++] = cartEntry;
                cartEntriesString.push("qty" + cartEntry.quantity + "productCode" + cartEntry.product.code)
            }
        }
        latestAddToCart.type = "MULTIPLE"
        latestAddToCart.cartEntries = cartEntries;
        latestAddToCart.token = $("meta[name='_csrf']").attr("content");
        if(fromPage !== "") {
            latestAddToCart.fromPage = fromPage;
        } else {
            latestAddToCart.fromPage = "PLP";
        }

        localStorage.setItem('cartEntries', cartEntriesString);
        bulkAddToCartPost(cartEntries, latestAddToCart.token, latestAddToCart.fromPage, '', isMultipleParts, isAddSomeParts);
	}
}

function addToCartPLPAssembly(productCode, quantity) {
        var cartEntries = [];
        var cartEntriesString = [];
        var cartEntry;

        cartEntry = { quantity: 0, product: { code: productCode } };
        if (quantity == undefined || quantity == "") {
            cartEntry.quantity = 1;
        } else {
            cartEntry.quantity += parseInt(quantity);
        }
        cartEntries[0] = cartEntry;
        cartEntriesString.push("qty" + cartEntry.quantity + "productCode" + cartEntry.product.code)


        latestAddToCart.type = "MULTIPLE"
        latestAddToCart.cartEntries = cartEntries;
        latestAddToCart.token = $("meta[name='_csrf']").attr("content");
        latestAddToCart.fromPage = "PLP";
        localStorage.setItem('cartEntries', cartEntriesString);
        bulkAddToCartPost(cartEntries, latestAddToCart.token, latestAddToCart.fromPage, '', false, false);
}

async function bulkAddToCartPost(cartEntries, token, fromPage, callback, isMultipleParts, isAddSomeParts) {
	if (typeof token == 'undefined') {
		var token = $("meta[name='_csrf']").attr("content");
	}
	var baseUrl = getCurrentBaseUrl();
	var endpoint = '';
	if (fromPage === "quickOrderPage") {
		endpoint = 'cart/addQuickOrder';
	} else {
		endpoint = 'cart/addGrid';
	}

	var payload = { "cartEntries": cartEntries };
	if (endpoint === 'cart/addGrid') {
		payload.recaptchaToken = await recaptcha.execute('cart_add');
	}
	var dataToSend = JSON.stringify(payload);

	addSpinner(".main", "top-20");
	$.ajax({
		type: 'POST',
		dataType: 'json',
		headers: {
			'CSRFToken': token,
			'Accept': '*',
			'Content-Type': 'application/json'
		},
		url: baseUrl + endpoint,
		data: dataToSend,
		success: function(data) {
			var errorMessage = JSON.stringify(data.quickOrderErrorData[0]);
			if (errorMessage != null) {
				var errorMessage = data.quickOrderErrorData[0].errorMsg;
				if (data.modalErrorAddToCartMessage) {
                    if (isMultipleParts && !isAddSomeParts) {
                        if(fromPage === multiplePartsAssembly) {
                            $('#somePartsAlreadyInCartPopup').find('.js-hide-cta').addClass('d-none');

                            var errorData = Object.values(data.quickOrderErrorData);
                            $('#somePartsAlreadyInCartPopup').find('.js-change-modal-text').text("");
                            for (var i = 0; i < errorData.length; i++) {
                                var p = errorData[i].errorMsg;
                                $('#somePartsAlreadyInCartPopup').find('.js-change-modal-text').append($('<p>'+ p +'</p><br>'));
                            }
                            if(localStorage.getItem("somePartAreAlreadyInCart") == 'true'){
                                localStorage.removeItem("somePartAreAlreadyInCart")
                                $('#somePartsAlreadyInCartPopup').find('.js-change-modal-text').append('<p>'+ $('#somePartsAlreadyInCartPopup').find('#modal-assembly-parts-are-already-cart').val() +'</p><br>');
                            }
                            $('#somePartsAlreadyInCartPopup').modal('show');
                        } else {
                            $('#somePartsAlreadyInCartPopup').modal('show');
                        }
                    }else if (isAddSomeParts) {
                        //NO NEED FOR THIS MODAL
                    }else {
					    appendAndShowPopup(data.dealerPopupContent, "#modal-cart-full");
                    }
				} else {
                    window.location.href = baseUrl + "dealerlocator";
				}
			} else {
			    if (fromPage === multiplePartsAssembly && isMultipleParts && !isAddSomeParts) {
                     showRightModals(data);
			    }if (!fromPage === multiplePartsAssembly && isMultipleParts && !isAddSomeParts) {
                    $('#somePartsAlreadyInCartPopup').modal('show');
			    }else if (isAddSomeParts) {
			        //NO NEED FOR THIS MODAL
			    }else {
				    showRightModals(data);
			    }
				if (callback !== undefined) {
					setTimeout(callback, 500);
				}
			}
            addToCartGraphicDesignDataLayer();
			console.log("added success!");
			updateCart();
		    emarsysPageLoad();
			cartHover();
			removeSpinner()
		},
		error: function(err) {
			console.log(err);
            removeSpinner();
        }
	});
}

function showRightModals(data, event) {
	//Show set preferred (This happens for logged user)
	if (data.showModalPreferredDealer !== 'undefined' && data.showModalPreferredDealer == "true") {
		$("#DealerFirstTrigger01").modal('hide');
		appendAndShowPopup(data.modalPreferredDealer, ".favourite-dealer-modal");
		document.body.style.overflow = "hidden";
		$(".favourite-dealer-modal").modal({
			show: true,
			backdrop: 'static',
			keyboard: false
		});
	}
	//Show added to cart if user have already a dealer in session showed on FE (otherwise there will be a refresh)
	else if (!$("#DealerFirstTrigger01").is(':visible') && $('.dealer-label').find('.dealer-off').length === 0) {
		$("#show-added-to-cart-modal").modal({
			show: true,
			backdrop: 'static',
			keyboard: false
		});

        if ($('.inPunchout').length != 0 && event != undefined) {
            var clickedHeight = event.clientY - 200;
            $("#show-added-to-cart-modal .modal-content").css({position:"absolute",top:clickedHeight});
        }
	} else if (data.showModalPreferredDealer == "false") {
		location.reload();
	}
}

