function buildRangeQueryString(facetName) {
	var facetRange = document.getElementById(facetName);
	var tokens = facetRange.value.split(':');
	var facetNameIndex = tokens.indexOf(facetName.toLowerCase());
	if (facetNameIndex > 0) {
		tokens.splice(facetNameIndex, 2);
	}

	facetRange.value = tokens.join(":");

	var facetRangeMin = document.getElementById(facetName + "Min");
	var facetRangeMax = document.getElementById(facetName + "Max");
	var decodedMin = facetRangeMin.value;
	var decodedMax = facetRangeMax.value;
	var parsedString = facetRange.value;
	parsedString += ":" + facetName.toLowerCase() + ":[" + decodedMin + "," + decodedMax + "]";
	facetRange.value = parsedString;
}

function loadSort() {
	$(".sortingjs").on("change", function() {
		var sort = $(this).val();
		$.urlParam = function(name) {
			var results = new RegExp('[\?&]' + name + '=([^&#]*)').exec(window.location.href);
			if (results == null) {
				return null;
			} else {
				return results.length >= 2 ? results[1] : null;
			}
		}
		var urlParams = 'sort=' + sort;
		if ($.urlParam('byModel') != null) {
			urlParams += '&byModel=' + $.urlParam('byModel');
		}
		if ($.urlParam('text') != null) {
			urlParams += '&text=' + $.urlParam('text');
		}
		if ($.urlParam('page') == null) {
			urlParams += '&page=0';
		}
		if ($.urlParam('pageSize') != null) {
			urlParams += '&pageSize=' + $.urlParam('pageSize');
		}
		if ($.urlParam('filter_product_code') != null) {
			urlParams += '&filter_product_code=' + $.urlParam('filter_product_code');
		}
		if ($.urlParam('q') != null) {
			urlParams += '&q=' + $.urlParam('q');
		}
        if ($.urlParam('selectedEquipCode') != null) {
            urlParams += '&selectedEquipCode=' + $.urlParam('selectedEquipCode');
        }
        if ($.urlParam('selectedModelCode') != null) {
            urlParams += '&selectedModelCode=' + $.urlParam('selectedModelCode');
        }
        if ($.urlParam('mktCode') != null) {
            urlParams += '&mktCode=' + $.urlParam('mktCode');
        }
        if ($.urlParam('isGuided') != null) {
            urlParams += '&isGuided=' + $.urlParam('isGuided');
        }
        if ($.urlParam('combinedSearch') != null) {
            urlParams += '&combinedSearch=' + $.urlParam('combinedSearch');
        }
        if ($.urlParam('isPartium') != null) {
            urlParams += '&isPartium=' + $.urlParam('isPartium');
        }
        if ($.urlParam('psid') != null) {
            urlParams += '&psid=' + $.urlParam('psid');
        }
        if ($.urlParam('pcm') != null) {
            urlParams += '&pcm=' + $.urlParam('pcm');
        }
        if ($.urlParam('attachmentModels') != null) {
            urlParams += '&attachmentModels=' + $.urlParam('attachmentModels');
        }
		$(location).attr('href', window.location.origin + window.location.pathname + '?' + urlParams);
	});
}

