//Start of Emarsys Web Extend
function getEmarsysBrandName(brand){

    var emarsysBrandName = '';

    switch(brand) {
        case 'A' : emarsysBrandName = "CIH"; break;
        case 'B' : emarsysBrandName = "NHAG"; break;
        case 'C' : emarsysBrandName = "STEYR"; break;
        case "default" : emarsysBrandName = "DEFAULT"; break;
        case 'E' : emarsysBrandName = "CASE"; break;
        case 'F' : emarsysBrandName = "NHCE"; break;
        case 'H' : emarsysBrandName = "KOBELCO"; break;
        case 'L' : emarsysBrandName = "K-LINE"; break;
        case 'O' : emarsysBrandName = "OVERUM"; break;
        case 'R' : emarsysBrandName = "RAVEN"; break;
        case 'W' : emarsysBrandName = "MILLER"; break;
        case 'X' : emarsysBrandName = "FLEXICOIL"; break;
        case 'Y' : emarsysBrandName = "Y"; break;
        case 'Z' : emarsysBrandName = "KONGSKILDE"; break;
        default : emarsysBrandName = ""; break;
    }

    return emarsysBrandName;
}

//Initialization
var webExtend = $('.js-web-extend');
var rate = webExtend.data('exchange-rate');
var storeCurrency = webExtend.data('store-currency');
var language = webExtend.data('language');
var currentUser = webExtend.data('current-user');
var exchangeRate = rate !== "" ? parseFloat(webExtend.data('exchange-rate')) : "";

function getConvertedPrice(price) {
    var finalPrice = "";

    if(price === "") {
        price = '0';
    }

    if(exchangeRate !== "") {
        finalPrice = price * exchangeRate;
    } else {
        finalPrice = price;
    }

    return parseFloat(finalPrice).toFixed(2);
}

function analyticsCartData() {
	if(webExtend.data('enable-web-extend')) {
        //Initialization
        var ScarabQueue = ScarabQueue || [];
        var url = window.location.origin + getCurrentBaseUrl() + "cart/analyticsCartData";
        var items = [];
        $.ajax({
            type : 'GET',
            url : url,
            async: false,
            success : function(data, status) {
                var cartEntryGroup = data;

                cartEntryGroup.forEach(function(entryGroup,i) {
                    if(entryGroup !== null && entryGroup.groupType.code === "VENDOR") {
                        entryGroup.children.forEach(function(cartEntry,i) {
                            cartEntry.orderEntries.forEach(function(entry,i) {
                                var brand = getEmarsysBrandName(entry.brand.code);
                                var price = getConvertedPrice(entry.totalPrice.value);
                                var item = {
                                    "item": entry.product.code + "-" + brand,
                                    "price": +price,
                                    "quantity": parseInt(entry.quantity)
                                }
                                items.push(item);
                            });
                        });
                    }
                });
            },
            error: function(e) {
                console.log(e);
            }
        });
        return JSON.stringify(items);
	}
}

function emarsysOrderData() {
	if($('.js-web-extend').data('enable-web-extend')) {
        var items = [];
        $.ajax({
			type: 'GET',
			dataType: 'json',
			async: false,
			url: getCurrentBaseUrl() + 'trackOrder/emarsysOrderData',
			data: { 
				"orderCode": $('#web-extend-purchase__data').data('order-number'),
				"email": $('#web-extend-purchase__data').data('order-email') 
			},
			success: function(data) {
				var rootGroups = data.rootGroups;
				rootGroups.forEach(function(group) {
					if (group.groupType.code == 'VENDOR') {
						var groupItems = [];
						group.children.forEach(function (childEntryGroup) {
							childEntryGroup.orderEntries.forEach(function (orderEntry){
								var product = orderEntry.product;
				                var price = getConvertedPrice(orderEntry.totalPrice.value);
				                var quantity = parseFloat(orderEntry.quantity);
				                var brand = getEmarsysBrandName(orderEntry.brand.code);
				                var itemID = product.code;
				                var item = {
				                	"item": itemID + "-" + brand,
				                    "price": +price,
				                    "quantity": quantity
				               	}
				               	items.push(item);
							});
						});
					}
	            });
			}
		});
        return JSON.stringify(items);
	}
}

function emarsysPageLoad() {
    if($('.js-web-extend').data('enable-web-extend')) {
        var emarsysLanguage = '';
        var emarsysView = '';
        var emarsysCategory = '';
        var emarsysOrder = '';
        var emarsysSearchTerm = '';
        var emarsysDataBuilder = [];

        if(currentUser !== "anonymous") {
           emarsysLanguage = "ScarabQueue.push(['setEmail', '" +  currentUser + "']);\n";
        }
        if ($("#pdp-detail-info-section").is(":visible")) {
            var brand = getEmarsysBrandName($('#product-page__data').data('current-brand'));
            var productCode = $('#product-page__data').data('product-code');
            var emarsysProductCode = productCode + "-" + brand;
            emarsysView = "ScarabQueue.push(['view','" + emarsysProductCode + "']);\n";
        }
        if ($(".plp-marketing").is(":visible")) {
            emarsysCategory = "ScarabQueue.push(['category', '"+ $('#web-extend-category__data').data('category-path') + "']);";
        }
        if ($('#web-extend-purchase__data').data('order-number') !== undefined && $('#web-extend-purchase__data').data('order-number') !== "") {
            emarsysOrder = "ScarabQueue.push(['purchase', {orderId: '" + $('#web-extend-purchase__data').data('order-number') + "', items: " + emarsysOrderData() + "}]);\n";
        }

        var enableEmarsysSearchTerm = localStorage.getItem("enableEmarsysSearchTerm");
        var searchTerm = localStorage.getItem("emarsysSearchTerm");

        if(enableEmarsysSearchTerm !== null && enableEmarsysSearchTerm === 'true'){
            var term = searchTerm !== 'undefined' || searchTerm !== null ? searchTerm : '';
            emarsysSearchTerm = "ScarabQueue.push(['searchTerm', '" +  term + "']);\n";
            localStorage.removeItem("enableEmarsysSearchTerm");
            localStorage.removeItem("emarsysSearchTerm");
        }

        emarsysDataBuilder.push(
            '<script>\n',
            "var ScarabQueue = ScarabQueue || [];\n",
            emarsysLanguage,
            emarsysSearchTerm,
            emarsysView,
            emarsysCategory,
            "ScarabQueue.push(['language', language]);\n",
            "ScarabQueue.push(['displayCurrency', storeCurrency]);\n",
            "ScarabQueue.push(['cart'," + analyticsCartData() + "]);\n",
            emarsysOrder,
            "ScarabQueue.push(['go']);\n",
            '</script>');
        $('body').append(emarsysDataBuilder.join(""));
    }
}

