function validatePartFromCartModals(productCode, quantity, cspsStock, isSubOwnership) {
    var partCode = [];
    partCode.push(productCode);

    var url = getCurrentBaseUrl() + "validatePartFromCart?productCodes=" + partCode;
    $.ajax({
        type : 'GET',
        url : url,
        data: {
            'urgentRequestDealerCode': null
        },
        success : function(data) {
            if (data.isAddToCart == "true") {
                addToCartFromModals(quantity, productCode, '', cspsStock, isSubOwnership);
            }else if (data.isSameVendor == "true") {
                $('#modal-product-already-exist').modal('show');
                removeSpinner();
            }else {
                $('body').append($(data.changeDealerInCartPopup));
                $('#modal-change-dealer').modal('show');
                removeSpinner();
            }
        },
        error: function(e) {
            console.log(e);
            removeSpinner();
        },
    });
};

async function addToCartFromModals(quantity, productCode, callback, cspsStock, isSubOwnership)
{
    if (typeof token == 'undefined') {
        var token = $("meta[name='_csrf']").attr("content");
    }
    var baseUrl = getCurrentBaseUrl();
    const recaptchaToken = await recaptcha.execute('cart_add');
    	$.ajax({
    		type: 'POST',
    		url: baseUrl + 'cart/add',
    		data: 'qty=' + quantity + '&productCodePost=' + productCode + '&CSRFToken=' + token + '&cspsStock=' + cspsStock + '&isSubOwnership=' + isSubOwnership + '&recaptchaToken=' + recaptchaToken,
    		dataType: 'json',
    		success: function(data) {
    			removeSpinner();
    			if (typeof data.quickOrderErrorData !== 'undefined' && data.quickOrderErrorData.length > 0) {
    				console.log("Error in add to cart.")
    				var errorMessage = data.quickOrderErrorData[0].errorMsg;
    				if (data.modalErrorAddToCartMessage) {
    					appendAndShowPopup(data.dealerPopupContent, "#modal-cart-full");
    				} else {
    					latestAddToCart.type = "SINGLE";
    					latestAddToCart.productCode = productCode;
    					latestAddToCart.quantity = quantity;
    					latestAddToCart.token = token;

    					appendAndShowPopup(data.dealerPopupContent);
    					$("#SelectDealerModal").modal("hide");
    				}
    			} else {
    				//track add to cart
    				showRightModals(data);
    				if (callback !== undefined) {
    					setTimeout(callback, 500);
    				}
    			}
    			updateCart();
    		    emarsysPageLoad();
    			cartHover();
    		},
    		error: function(e) {
                removeSpinner();
                console.log(e);
            },
    	});
}

