function contactUsSelectedOption(){
     var contactOption = $('#modal-contact-us').find('#contactOption').val();
     var contactEmail = $('#modal-contact-us').find('.emailInput');
     var contactPhone = $('#modal-contact-us').find('.phoneInput');
     var emailHasError = contactEmail.find('.form-bg-error').length > 0 && contactEmail.find('small[data-error-field="true"]').length > 0;
     var phoneHasError = contactPhone.find('.form-bg-error').length > 0 && contactPhone.find('small[data-error-field="true"]').length > 0;

        if(contactOption !== '' && contactOption === 'email'){
            contactEmail.find('input').attr("data-mandatory", "true");
            contactPhone.find('input').removeAttr("data-mandatory", "true");
            if(phoneHasError){
                contactPhone.find('.form-bg-error').remove();
                contactPhone.find('small[data-error-field="true"]').remove();
            }
        } else if(contactOption !== '' && contactOption === 'phone'){
            contactPhone.find('input').attr("data-mandatory", "true");
            contactEmail.find('input').removeAttr("data-mandatory", "true");
            if(contactEmail){
                contactEmail.find('.form-bg-error').remove();
                contactEmail.find('small[data-error-field="true"]').remove();
            }
        }
}

