function getWishlists(anonymous, e) {
	localStorage.setItem("wishListData", e.getAttribute('data-product-details'));
	localStorage.setItem("wishListProductPrice", e.getAttribute('data-product-price'));
	if (anonymous === true) {
		$('#autentication-modal').modal({
			show: true
		});
	} else {
		var productCodeWishList = $("#product-code-wishlist");
		//remove product code inside wishlist modal every open it
		productCodeWishList.val('');
		productCodeWishList.val($(event.target).parent().attr("product-code"));
		//FOR IE in case product code was not been set inside wishlist modal
		if (productCodeWishList.val() == '') {
			productCodeWishList.val(event.target.getAttribute("product-code"));
		}
		var baseUrl = getCurrentBaseUrl();
		$.ajax({
			type: 'POST',
			url: baseUrl + 'my-account/wishlist/getsWishlists',
			data: {
				CSRFToken: $('#csfr_token').val()
			},
			success: function(data) {
				for (var i = 0; i < data.wishlist.length; i++) {
				    var wishlistName = '';
				    if(data.wishlist[i].name == 'DEFAULT SHOPPING LIST' ){
				        wishlistName = $('#appenderWishlist').data('wishlist-name');
				    }else{
				        wishlistName = data.wishlist[i].name;
				    }

					var wishlistTag = "   <div class=\"my-2 col-12\"><div class=\"modal-wishlist-container__item-box input-container-special__radio radios-wishlists\" data-radio-name=\"name0\">" +
                    "<input value=\"" + data.wishlist[i].code + "\" data-mandatory=\"true\" data-marketing-radio=\"true\" type=\"radio\" id=\"" + i + "\" name=\"wishlistName\">" +
                    "<label for=\"" + i + "\"> " + wishlistName + " </label></div></div>";
					$("#appenderWishlist").prepend(wishlistTag);
					$($('input[name=wishlistName]')[0]).prop("checked", true);
				}
				console.log(data);
			},
			error: function(e) {
				//Add logic when available
				console.log(e);
			}
		});
	}
}

