// --- List and grid view from app.js
function setCookie(cookieName, cookieValue, exdays) {
	var d = new Date();
	d.setTime(d.getTime() + (exdays * 24 * 60 * 60 * 1000));
	var expires = "expires=" + d.toUTCString();
	document.cookie = cookieName + "=" + cookieValue + ";" + expires + ";path=/";
}

function getCookie(cookieName) {
	var name = cookieName + "=";
	var decodedCookie = decodeURIComponent(document.cookie);
	var ca = decodedCookie.split(';');
	for (var i = 0; i < ca.length; i++) {
		var c = ca[i];
		while (c.charAt(0) == ' ') {
			c = c.substring(1);
		}
		if (c.indexOf(name) == 0) {
			return c.substring(name.length, c.length);
		}
	}
	return "";
}

function dealerSelectedEvent(event) {
    addSpinner(".main", "top-20");
	var currentTarget = event.currentTarget;
	var parentTarget = currentTarget.parentElement;
	var action = $(parentTarget).attr("action");
	var data = $(parentTarget).serialize();
	$.post(action, data).done(function(data) {
		if (typeof latestAddToCart !== 'undefined') {
			if (latestAddToCart.type === "SINGLE") {
				if (latestAddToCart.isComingFromWishlist === true) {
					addWishlistToCartPost(latestAddToCart.productCode, latestAddToCart.quantity, latestAddToCart.brandCode, latestAddToCart.token, function() {
						//First time user select dealer, it is saved in session
						if ($('.logged-label').length === 0 && $('.dealer-label').find('.logged-dealer').length === 0) {
							location.reload();
						}
					});
				} else if (latestAddToCart.from !== 'undefined' && latestAddToCart.from == 'PDP') {
					var parameter = "&isInUseQuantity=true";
					addToCartPost(latestAddToCart.productCode, latestAddToCart.quantity, latestAddToCart.token, function() {
						$("#DealerFirstTrigger01").modal('hide');
						if ($('.logged-label').length === 0 && $('.dealer-label').find('.logged-dealer').length === 0) {
							location.reload();
						}
					}, parameter);
				} else {
					addToCartPost(latestAddToCart.productCode, latestAddToCart.quantity, latestAddToCart.token, function() {
						$("#DealerFirstTrigger01").modal('hide');
						if ($('.logged-label').length === 0 && $('.dealer-label').find('.logged-dealer').length === 0) {
							location.reload();
						}
					});
				}
			}
			if (latestAddToCart.type === "MULTIPLE") {
				bulkAddToCartPost(latestAddToCart.cartEntries, latestAddToCart.token, latestAddToCart.fromPage, function() {
					$("#DealerFirstTrigger01").modal('hide');
					if ($('.logged-label').length === 0 && $('.dealer-label').find('.logged-dealer').length === 0) {
						location.reload();
					}
				});
			}
		}
		removeSpinner();
		window.location.reload();
	});
}

