// --- Sorting for the dealer modal from app.js
var sortList = function sortList(target, ord, data, dateFormat) {
	var $parent = target.parent();

	if (ord.toLowerCase() == 'asc') {
		if (dateFormat) {
			target.sort(ascSortByDataDateTime(data, dateFormat));
		} else {
			target.sort(ascSortByData(data));
		}
	} else {
		if (dateFormat) {
			target.sort(descSortByDataDateTime(data, dateFormat));
		} else {
			target.sort(descSortByData(data));
		}
	}

	target.appendTo($parent);
};

function ascSortByDataDateTime(data, dateFormat) {
	return function(a, b) {
		return toDateFormat($(b).find(data).text(), dateFormat) < toDateFormat($(a).find(data).text(), dateFormat) ? 1 : toDateFormat($(b).find(data).text(), dateFormat) > toDateFormat($(a).find(data).text(), dateFormat) ? -1 : 0;
	};
}

function descSortByDataDateTime(data, dateFormat) {
	return function(a, b) {
		return toDateFormat($(b).find(data).text(), dateFormat) > toDateFormat($(a).find(data).text(), dateFormat) ? 1 : toDateFormat($(b).find(data).text(), dateFormat) < toDateFormat($(a).find(data).text(), dateFormat) ? -1 : 0;
	};
}

function toDateFormat(dateString, dateFormat) {
	return moment(dateString, dateFormat).toDate();
}

function ascSortByData(data) {
	return function(a, b) {
		return $(b).find(data).text() < $(a).find(data).text() ? 1 : $(b).find(data).text() > $(a).find(data).text() ? -1 : 0;
	};
}

function descSortByData(data) {
	return function(a, b) {
		return $(b).find(data).text() > $(a).find(data).text() ? 1 : $(b).find(data).text() < $(a).find(data).text() ? -1 : 0;
	};
}
// --- End of: Sorting for the dealer modal from app.js

