function carousel(screenWidth){
    var bundleSize = $("#product-bundle-maxItem").val();
    var itemsShow = 3;
    var loopItem = true;
    var widthItem = false;
      if(bundleSize == 1)
      {
            itemsShow = 1;
            loopItem = false;
            widthItem = true;
            $(".owl-item").addClass('bundle-item-style');
      }
      else if(bundleSize == 2)
      {
            loopItem = false;
            itemsShow = 2;
            if(screenWidth == 'mobile')
            {
                $("#bundle-style").addClass('bundle-style-mobile');
                $("#bundle-style").removeClass('bundle-style-2');
                $(".owl-item").removeClass('bundle-item-style');
            }
            else
            {
                $("#bundle-style").removeClass('bundle-style-mobile');
                $("#bundle-style").addClass('bundle-style-2');
                $(".owl-item").addClass('bundle-item-style');
            }
      }

        $('.owl-carousel').owlCarousel({
            loop:loopItem,
            margin:10,
            autoWidth: widthItem,
            center:widthItem,
            nav:true,
            navElement: 'a',
                navClass: ['btn btn-secondary btn-square owl-prev', 'btn btn-secondary btn-square owl-next'],
                navText: ['<i class="icon-previous"></i>', '<i class="icon-next"></i>'],
            responsive:{
                0:{
                    nav:false,
                    items:2
                },
                992:{
                    items:itemsShow
                }
            }
        });

}

