var clearVertexErrorMessage = function() {
    var $div = $('#vertex-error-message');
    if ($div.length > 0) {
        $div.empty();
    }
}

$('#btnConfirmModuleBillingAddress').on('click', function() {
    clearVertexErrorMessage();
    var isRequestChanged = 'true';
    if($("#fedExValidation").length>0)
    {
        isRequestChanged = $("#fedExValidation")[0].getAttribute("data-changed");
        $('<input />').attr('type', 'hidden')
                .attr('name', "toBeValidated")
                .attr('value', isRequestChanged === "true")
                .appendTo('#silentOrderPostForm');

        $("#fedExValidation")[0].setAttribute("data-changed", false);
    }

    var validationError = 'false';
    $('input[id*=address]').each(function(){
        if ($(this).next('.form-bg-error').length) {
            $(this).next('.form-bg-error').remove();
            $(this).next('[data-error-field="true"]').remove();
        }

        if($(this).data('mandatory') == true &&  $(this).val() == ""){
            validationError = true;
            $(this).after('<div class="form-bg-error" style="content: &quot;&quot;; position: absolute; bottom: 1px; top: auto; left: 1px;"></div><small data-error-field="true" class="text-danger">' + $(this).data('msg-required') + '</small>');
        }

        if($(this).attr("id") == "address.postcode" && $(this).val().length < 5){
            validationError = true;
            $(this).after('<div class="form-bg-error" style="content: &quot;&quot;; position: absolute; bottom: 1px; top: auto; left: 1px;"></div><small data-error-field="true" class="text-danger">' + $(this).data('msg-required') + '</small>');
        }

    });

    if ($("#regionIso").length != 0) {
        $("#regionIso").next('.form-bg-error').remove();
        $("#regionIso").next('[data-error-field="true"]').remove();

        if($("#regionIso").val() == "" || $("#regionIso").val() == null){
            validationError = true;
            $("#regionIso").after('<div class="form-bg-error" style="content: &quot;&quot;; position: absolute; bottom: 1px; top: auto; left: 1px;"></div><small data-error-field="true" class="text-danger">' + $("#regionIso").data('msg-required') + '</small>');
        }
    }

    if($('#requestTaxExempt').is(':checked')) {
        var fileSection = $("#cart-order-summary__file");
        if (fileSection.length === 0) {
            validationError = true;
            $('#tax-exempt-doc-required').remove();
            $("#tax-checkbox-container").after('<div class="col-12 pt-1" id="tax-exempt-doc-required"><div class="form-error upload-error" style="content: &quot;&quot;; position: absolute; bottom: 1px; top: auto; left: 15px;"></div><small class="text-danger">' + $("#taxUploadFileRequired").val() + '</small></div>');
            $('html, body').animate({
                scrollTop: $(".exemption-tax").offset().top  - $('#header').height() - 50
            }, 0);
        }
    }

    if(validationError == 'false'){
        var data = $('#silentOrderPostForm').serialize();
        $('#silentOrderPostForm input[type="hidden"]').remove();

        var url = getCurrentBaseUrl() + "checkout/multi/billing/add#checkout-wizard-billing";
        $.post(url, data)
            .done(function(text) {
                $("#fedExValidation")[0].style.display = "none";
                if(text.includes("VertexError"))
                {
                    var vertexErrorMessage = text.replace("VertexError:", "");
                    var errorMessageDiv = $("#vertex-error-message");
                     $(errorMessageDiv).append("<span>" + vertexErrorMessage +"</span>");
                    $('html, body').animate({
                        scrollTop: $('#vertex-error-message').offset().top - $('#header').height() - 50
                    }, 0);
                    $("#btnConfirmModule").attr("disabled", false);
                }
                else
                {
                    window.location.href = getCurrentBaseUrl() + "checkout/multi/payment-method/add#checkout-wizard-payment";
                }
            })
            .fail(function(jqXHR, textStatus, errorThrown) {
                $("#btnConfirmModule").attr("disabled", false);
                var fedexError = $("#fedExValidation")[0];

                var message = $("#fedExValidationIncompleteAddress").html();
                if (jqXHR.status === 404 || jqXHR.status === 500) {
                    message = $("#fedExValidationFail").html();
                }
                $(fedexError).html(message);
                $(fedexError).prepend("<i class='exclmark icon'>");
                fedexError.style.display = "block";
                $('html, body').animate({
                    scrollTop: $(".fedexValidationBox").offset().top
                }, 0);
            });
        }

});


