$('#modelVehicle').on('input', function () {
        var modelId = $('#modelVehicle').val().trim();
    	var baseUrl = getCurrentBaseUrl();
		var waitTimeBeforeRequest = $(this).attr("data-waitTimeBeforeRequest");

    	$('#modelVehicle').addClass("input-has-value");
    	if(modelId.length > 0){
			if (requestTimer) {
				clearTimeout(requestTimer);
			}
			requestTimer = setTimeout(function() {
				$.ajax({
					type: 'GET',
					url: baseUrl + 'personalarea/myvehicles/getModelsById',
					data: { modelId: modelId },
					success: function(data, textStatus, jqXHR) {
						$('.autocomplete-items').remove();
						addSpinner('#insert-model-modal', 'top-10');
						var modelsForVehiclesJson = JSON.parse(data);
						var modelsForVehicles = modelsForVehiclesJson.modelsForVehicle;
						clearVehicleUl();
						if (modelsForVehicles.length != 0) {
							document.querySelector('.sn-pin-error').innerText = '';
							$('#modelVehicle').addClass("input-has-value autocomplete-input");
							var ul = document.createElement('ul');
							ul.id = 'search-by-model-autocomplete-list';
							ul.className = 'autocomplete-items ';
							var insertSNBox = document.getElementById('modelVehicle');
							insertSNBox.parentNode.insertBefore(ul, insertSNBox.nextSibling);
							serialNumberObject.renderHtmlScript(JSON.stringify(JSON.parse(data).modelsForVehicle), $("#search-by-model-autocomplete-list"), createModelVehicleLi);
							$('.errMsg').addClass('d-none');
							removeSpinner();
						} else {
							document.querySelector('.sn-pin-error').innerText = '';
							if (modelId.length > 2) {
								$('.errMsg').removeClass('d-none');
							}
							$('#modelVehicle').removeClass("autocomplete-input");
							$('.autocomplete-items').remove();
							removeSpinner();
						}
					},
					error: function(err) {
						document.querySelector('.sn-pin-error').innerText = err.responseText.replace(/"/gi, '');
						$('#modelVehicle').removeClass("input-has-value");
						$('.autocomplete-items').remove();
						removeSpinner();
					}
				});
			}, waitTimeBeforeRequest);
        }else{
            document.getElementById('modelVehicle').value = '';
            document.querySelector('.sn-pin-error').innerText = '';
            $('.errMsg').addClass('d-none');
            $('.autocomplete-items').remove();
            $('#modelVehicle').removeClass("input-has-value");
            removeSpinner();
        }
});

