function cleanSession(site, language, label) {
	event.preventDefault();
	var baseUrl = getCurrentBaseUrl();
	$.ajax({
		type: 'GET',
		url: baseUrl + 'languageSelector/onSiteChange',
		data: { site: site, language: language },
		async: false,
		success: function(data) {
			window.location.href = data;
			selectMarketEvent(site, language, label);
		},
		error: function(err) {
			console.log(err);
		}
	});
}

