async function applyCoupon(event) {
	var currentTarget = $(event.target);
	var dealerCode = currentTarget.attr("data-dealerCode");
	var brandCode = currentTarget.attr("data-brand");
	var couponCode = currentTarget.closest(".input-group").find(".input-promo-code").val();
	var baseUrl = getCurrentBaseUrl();

    var errorElement = $('#' + dealerCode).find(".coupon-error-msg");
    errorElement.addClass('d-none');

    const recaptchaToken = await recaptcha.execute('coupon');

    $.ajax({
        type: 'POST',
        url: baseUrl + 'cart/coupon/apply',
        data: {
            couponCode: couponCode,
            couponDealerCode: dealerCode, //couponDealerCode:dealerCode
            brandCode: brandCode,
            recaptchaToken: recaptchaToken
        },
        success: function(data) {
            var currentPageUrl = window.location.href;
            $.ajax({
                type: 'GET',
                url: currentPageUrl,
                success: function(data) {
                    var checkoutResumeHTML = $(data).find('.checkout-resume')[0];
                    var checkoutEntriesResumeHTML = $(data).find('.checkout-entries-resume')[0];
					$('.checkout-resume').replaceWith(checkoutResumeHTML);
					$('.checkout-entries-resume').replaceWith(checkoutEntriesResumeHTML);
					if(currentPageUrl.includes('checkout-wizard-billing'))
					{
                       $("input[name='delivery_method']").attr("disabled", true);
                       $("input[name='delivery_method']").next("label").addClass('disable-element');
					}
                },
                error: function(e) {
                    console.log(e);
                }
            });
        },
        error: function(data) {
            var errorMsg = data.responseJSON;
            if (errorMsg) {
                handlePromoCodeInvalid(currentTarget, errorMsg);
            }
        }
    });
}

