function handlePromoCodeInvalid(currentTarget, errorMsg) {
  var $container = currentTarget.closest('.promo-code-section');
  var $errorContainer = $container.find('.invalid-code-container');
  $errorContainer.find('[data-error="true"]').remove();
  $errorContainer.removeClass('d-none');

  var errorLabel = '<p data-error="true" class="invalid-code coupon-error-msg">' + errorMsg + '</p>';
  $errorContainer.append(errorLabel);
}

function removeCoupon(couponCode) {
    var baseUrl = getCurrentBaseUrl();
    $.ajax({
        type: 'POST',
        data: JSON.stringify({"couponCode" : couponCode}),
        contentType: 'application/json',
        url: baseUrl + 'cart/coupon/remove',
        success: function() {
            var currentPageUrl = window.location.href;
            $.ajax({
                type: 'GET',
                url: currentPageUrl,
                success: function(data) {
                    var checkoutResumeHTML = $(data).find('.checkout-resume')[0];
                    var checkoutEntriesResumeHTML = $(data).find('.checkout-entries-resume')[0];
                    $('.checkout-resume').replaceWith(checkoutResumeHTML);
                    $('.checkout-entries-resume').replaceWith(checkoutEntriesResumeHTML);
                    if(currentPageUrl.includes('checkout-wizard-billing'))
                    {
                       $("input[name='delivery_method']").attr("disabled", true);
                       $("input[name='delivery_method']").next("label").addClass('disable-element');
                    }
                },
                error: function(e) {
                    console.log(e);
                }
            });
        },
    });
}

// Function to remove the class when the screen width is 767 or less
function addClassBasedOnScreenSize() {

    if (window.innerWidth <= 767) {
        //$('.quantity-quick-order').removeClass('pt-2');
    }
    if(window.innerWidth < 992) {
        $('.card-info-detail-container').addClass('card-info-detail-container-mobile-active-card');
        $('.toolbox-py').addClass('py-1');
        $('.wish-button').addClass('status-like');
    }
    else {
        // Add the class if the screen size is greater than 767
        //$('.quantity-quick-order').addClass('pt-2');
        $('.card-info-detail-container').removeClass('card-info-detail-container-mobile-active-card');
        $('.toolbox-py').removeClass('py-1');
        $('.wish-button').removeClass('status-like');
    }
}

