function addQuickOrderProduct() {
	var errorMessageMax = $(".product-add-button").attr("data-error-message-max");
	var errorMessageExists = $(".product-add-button").attr("data-error-message-exists");
	var errorMessageUnavailable = $(".product-add-button").attr("data-error-message-unavailable");
	var prodId = $($(".add-order")[0]).attr("id");
	if (prodId === "") {
		var prodCode = document.getElementById("prodCode").value;
	} else {
		var prodCode = prodId;
	}

	if (!prodCode || prodCode.trim() === "") {
		windowShowMessage("Please enter a part number");
		return;
	}

    controlQuickOrderDisplay();

	var productLimit = $('#quick-order-max-upload').val();
	var baseUrl = getCurrentBaseUrl();
	var currentNumberOfProducts = $('.table-item').length - 1;
	var productPresent = windowProductExist(prodCode);
	if (!productPresent) {
		var $addButton = $(".product-add-button");
		var originalButtonText = $addButton.text();

		addSpinner('.quick-order-page', 'top-20');
		$addButton.prop('disabled', true);

		$.ajax({
			type: 'GET',
			dataType: 'json',
			url: baseUrl + 'quickOrder/productInfo',
			data: { "code": prodCode },
			success: function(data) {
				var rawParams = {
						template: "quick-order",
					};
				if (currentNumberOfProducts < productLimit && data.errorMsg === null) {
					serialNumberObject.renderHtmlScriptWithParams(JSON.stringify(data), $(".quick-orders-table .products-list"), createQuickOrderProduct, rawParams);
                    addClassBasedOnScreenSize();
					$('.hide-section').remove();
					$(".error-message").empty();
					$("#prodCode").val("");
					var btnContainer = $(".add-order");
					$('.clear-all-btn').removeClass('disable-element');
                    btnContainer.each(function () {
                        $(this).attr("id", "");
                    });
                    gtmAddPlacement(prodCode);
				} else {
				    if (data.errorMsg == 'unableToAddProduct')  {
				        windowShowMessage(errorMessageUnavailable);
				    }
					else if (currentNumberOfProducts === productLimit) {
						windowShowMessage(errorMessageMax);
					} else {
						windowShowMessage(errorMessageExists);
					}
				}
			},
			error: function(e) {
				console.log("Error loading product info:", e);
				windowShowMessage("Failed to load product. Please try again.");
			},
			complete: function() {
				removeSpinner();
				$addButton.prop('disabled', false);
			}
		});
	}
}

windowDeleteProduct = function (productCode) {
  var row = $(".quick-orders-table .table-item[data-product-code=" + productCode + "]");
  row.remove();
};

 function windowShowMessage(attributeMessage) {
  var emptyLine = $(".empty-line");
  emptyLine.find(".error-message").text(attributeMessage);
}

function windowProductExist(productCode) {
  var items = $(".quick-orders-table .table-item");
  var exists = false;

  if (items.length > 0) {
    for (var i = 0; i < items.length; i++) {
      var currentCode = items[i].getAttribute("data-product-code");

      if (currentCode == productCode) {
        windowShowMessage(items[i].getAttribute("data-existing-message"));
        exists = true;
      }
    }
  }

  return exists;
}

