function getEncodedProductCode(productCode)
{
    if (typeof productCode === 'string')
    {
        return productCode.replace(/([!"#$%&'()*+,.\/:;<=>?@[\\\]^`{|}~])/g, '\\$1');
    }

  return productCode;
}

