async function quickOrderAddToCartV2(checkedProducts,  isMultipleParts, isAddSomeParts)
{
    try {
        let maxVal = $('#quick-order-max-add-to-cart').val();
        const recaptchaToken = await recaptcha.execute('cart_add_quick');
		for (var m = 0; m < checkedProducts.length; m++) {

		    if(m == maxVal){
		        break;
		    }

			var productCode = checkedProducts[m].id;
			var dealerStock = $(checkedProducts[m]).data("dealer-stock-quantity");
			var subOwnershipStock = $(checkedProducts[m]).data("subownership-stock");
			let encodedProductCode = getEncodedProductCode(productCode);
            var quickOrder = $('.quantity-quick-order[data-product-id="' + productCode.replace(/\\/g, '\\\\') + '"]');
            var quantity = quickOrder[0].value;
			var cartEntry = {
                quantity: quantity,
                productCode: productCode,
                dealerStock: dealerStock,
                subOwnershipStock: subOwnershipStock
            };
			await callQuickOrderAddToCart(cartEntry, recaptchaToken);
			$(".quick-orders-table .table-item[data-product-code=" + encodedProductCode + "]").remove();
		}

        resolveQuickOrder(isMultipleParts, isAddSomeParts);
    } catch (error) {
        console.log(error);
        removeSpinner();
    }
}

function resolveQuickOrder(isMultipleParts, isAddSomeParts)
{
    $.ajax({
        url: getCurrentBaseUrl() + 'cart/quickOrder/resolve',
        method: 'post',
        contentType: "application/json",
        success : function(data)
        {
            var errorMessage = JSON.stringify(data.quickOrderErrorData[0]);
			if (errorMessage != null) {
				var errorMessage = data.quickOrderErrorData[0].errorMsg;
				if (data.modalErrorAddToCartMessage) {
                    if (isMultipleParts && !isAddSomeParts) {
                        $('#somePartsAlreadyInCartPopup').modal('show');
                    }else if (isAddSomeParts) {
                        //NO NEED FOR THIS MODAL
                    }else {
					    appendAndShowPopup(data.dealerPopupContent, "#modal-cart-full");
                    }
				} else {
                    window.location.href = baseUrl + "dealerlocator";
				}
			} else {
			    if (isMultipleParts && !isAddSomeParts) {
                    $('#somePartsAlreadyInCartPopup').modal('show');
			    }else if (isAddSomeParts) {
			        //NO NEED FOR THIS MODAL
			    }else {
				    showRightModals(data);
			    }
			}
            addToCartGraphicDesignDataLayer();
			console.log("added success!");
			updateCart();
			cartHover();
			removeSpinner()
        },
        error : function(err){
            console.log(err)
        }
    });
}

async function callQuickOrderAddToCart(cartEntry, recaptchaToken)
{
    return await $.ajax({
        url: getCurrentBaseUrl() + '/cart/addQuickOrderProduct',
        method: 'post',
        data: JSON.stringify({'productCode' : cartEntry.productCode, 'quantity' : cartEntry.quantity, 'dealerStock' : cartEntry.dealerStock, 'subOwnershipStock' : cartEntry.subOwnershipStock, 'recaptchaToken' : recaptchaToken}),
        contentType: "application/json"
    });
}

$("#csvFileInput").change(function(event) {
	event.preventDefault();
	controlQuickOrderDisplay();
	const input = document.getElementById("csvFileInput");
	var fd = new FormData();
	fd.append('file', input.files[0]);
	const fileName = input.files[0].name;
	const TypeFile = input.files[0].type;
	const fileType = TypeFile.substr(TypeFile.length - 3);
    var csvError = $('.js-non-csv-error');
	var baseUrl = getCurrentBaseUrl();
	addSpinner('.main','top-20')
	$.ajax({
		url: baseUrl + 'quickOrder/uploadQuickOrder',
		type: 'post',
		data: fd,
		contentType: false,
		processData: false,
		success: function(response) {
			$('#quick-order-empty-template').addClass("d-none");
			$('.addPartBtn').removeClass("d-none");
			var modalErrorText = "";
			var quantyModifiedMsg =  "";
			var pCode = "";
			var errorMsgCount = [];
			var rawParams = {
					template: "quick-order-upload",
				};
			for (var i = 0; i < response.length; i++) {
				var current = response[i];
				if (current.errorMsg === null) {
					if (!isProductPresent(current.productData.code))
					{
						if(current.notificationMessage != null)
						{
						    quantyModifiedMsg = current.notificationMessage;
						}
						serialNumberObject.renderHtmlScriptWithParams(JSON.stringify(response[i]), $(".quick-orders-table .products-list"), createQuickOrderProduct, rawParams);
                        $(".js-notif-msgs").each(function(i, obj){
                            if(current.productData.stock.stockLevel !== 0 && current.notificationMessage != null && $(obj).data("product-code") == current.productData.code) {
                               if($(obj).hasClass("d-none")){
                                   $(obj).removeClass("d-none");
                               }
                            }
                        });
						$('.clear-all-btn').removeClass('disable-element');
                            window.dataLayer = window.dataLayer || [];
                            window.dataLayer.push({
                                "event": "file_upload",
                                "file_name": fileName,
                                "file_extension": fileType
                            });
					}
					else
					{
						current.productData = current.productData.code;
						serialNumberObject.renderHtmlScript(JSON.stringify(current), $(".quick-orders-table .products-list"), createQuickOrderNewItem);
						$("#" + current.productData + "remove").find(".error-message").text($('.table-item[data-product-code="' + current.productData + '"]').attr("data-existing-message"));
					}
				} else if (current.productData === null) {
					current.productData = current.errorMsg;
					serialNumberObject.renderHtmlScript(JSON.stringify(current), $(".quick-orders-table .products-list"), createQuickOrderNewItem);
				} else {
					modalErrorText = current.errorMsg;
					pCode += current.productData.code + ', ';
					errorMsgCount.push(current.errorMsg);
				}
			}
			if (modalErrorText !== "" || quantyModifiedMsg !== "") {
                if(pCode !== "")
                {
                    modalErrorText += pCode;
                    modalErrorText = response.length > 1 ? modalErrorText.slice(0, -2) + ' products! ' : modalErrorText.slice(0, -2) + ' product! ';
                }
				$('#error-modal').modal('show');
				$("#error-modal #error-message-text").text(modalErrorText);
				if(quantyModifiedMsg !== "")
                {
                    if($('#error-modal #error-message-text').text() !== '') {
                        $('#error-message-text').after('<br>');
                    }
                    $("#error-modal #qty-modified-text").text(quantyModifiedMsg);
                }
			}
			removeSpinner();
			if(!csvError.hasClass('d-none')) {
                csvError.addClass('d-none');
            }
			addClassBasedOnScreenSize();
		},
		error: function(e) {
		    console.log(e);
		    removeSpinner();
		    if(csvError.hasClass('d-none')) {
                csvError.removeClass('d-none');
		    }
		}
	});
});

