function addToCartSmartEquip(data) {
	var token = $("meta[name='_csrf']").attr("content");
	var baseUrl = getCurrentBaseUrl();
	var dataToSend = JSON.stringify({ "cartEntries": data });
	$.ajax({
		type: 'POST',
		dataType: 'json',
		headers: {
			'CSRFToken': token,
			'Accept': '*',
			'Content-Type': 'application/json'
		},
		url: baseUrl + 'cart/add/smartEquip',
		data: dataToSend,
		success: function(data) {
			var errorMessage = JSON.stringify(data.quickOrderErrorData[0]);
			if (errorMessage != null) {
				var errorMessage = data.quickOrderErrorData[0].errorMsg;
				if (data.modalErrorAddToCartMessage) {
					appendAndShowPopup(data.dealerPopupContent, "#modal-cart-full");
				} else {
					appendAndShowPopup(data.dealerPopupContent);
				}
			} else {
				showRightModals(data);
			}
			console.log("added success!");
			updateCart();
		    emarsysPageLoad();
			cartHover();
		}
	});
}

function isProductPresent(productCode) {
	var items = $(".quick-orders-table .table-item");
	var exists = false;

	if (items.length > 0) {
		for (var i = 0; i < items.length; i++) {
			var currentCode = items[i].getAttribute("data-product-code");
			if (currentCode == productCode) {
				exists = true;
			}
		}
	}
	return exists;
}

