function addToCartProcurementSystem(goToCheckout) {
	var baseUrl = getCurrentBaseUrl();
	$.ajax({
		type: 'GET',
		dataType: 'json',
		url: baseUrl + 'punchout/requisition',
		data: {
			"cartEntries": localStorage.getItem('cartEntries'),
			"productCode": localStorage.getItem('productCode'),
			"quantity": localStorage.getItem('quantity'),
			"go_to_checkout": goToCheckout
		},
		success: function(data) {
			var addToCart = { item: data, type: 'dsp-addToCart' };
			localStorage.removeItem('cartEntries');
			localStorage.removeItem('productCode');
			localStorage.removeItem('quantity');
			window.parent.postMessage(addToCart, '*');
		},
		error: function(err) {
			localStorage.removeItem('cartEntries');
			localStorage.removeItem('productCode');
			localStorage.removeItem('quantity');
			console.log(err);
		}
	})
}

