function getDealers(brandCode) {
	var baseUrl = getCurrentBaseUrl();
	$.ajax({
		type: 'GET',
		url: baseUrl + 'personalarea/mydealers/getDealers',
        data: 'brandCode=' + brandCode,
		success: function(data) {
            data.forEach(function(dealer) {
                var dealerObject = dealerModule.getDealerInfoObject(dealer);
                var dealerRow = dealerModule.createPreferredDealerModalRow(dealerObject, brandCode, dealer.market);
                $(".preferred-dealers-list").append(dealerRow);
            });
		},
		error: function(err) {
		    console.log(err);
		}
	});
}

const dealerModule = (function() {
    var dealer = {code: '', name: '', city:'', state:'', zipCode:''};

    function getDealerInfoObject(dealerObj) {
        if (dealerObj) {
        	dealer = {code: '', name: '', city:'', state:'', zipCode:''};
            if (dealerObj.name) dealer.name = dealerObj.name;
            if (dealerObj.code) dealer.code = dealerObj.code;
            if (dealerObj.address && dealerObj.address.town) dealer.city = dealerObj.address.town;
            if (dealerObj.address && dealerObj.address.region && dealerObj.address.region.isocodeShort) dealer.state = dealerObj.address.region.isocodeShort;
            if (dealerObj.address && dealerObj.address.postalCode) dealer.zipCode = dealerObj.address.postalCode;
            if (dealerObj.address && dealerObj.address.country) dealer.countryCode = dealerObj.address.country.isocode;
        }

        return dealer;
    }

    function createPreferredDealerModalRow(dealer, brand, market) {
        var $template = $.parseHTML($('#preferredDealerRowTemplate').html());
        $($template).find(".name-value").text(dealer.name);
        $($template).find(".city-value").text(dealer.city);
        $($template).find(".state-value").text(dealer.state);
        $($template).find(".zip-value").text(dealer.zipCode);
        $($template).find(".country-value").text(dealer.countryCode);
        $($template).find(".select-dealer").attr('onclick', 'addPreferredDealer("' + dealer.code + '","' + brand + '","' + market + '")');
        $($template).find(".select-dealer").attr('data-market', market);

        return $template;
    }

    function filterDealers() {
        addSpinner('.preferred-dealers-list', 'top-30');
        var name = $('.type-filter-model-name').val();
        var country = $('.type-filter-model-country option:selected').val();
        var state = $('.type-filter-model-state').val();
        applyFilter(name, country, state);
        removeSpinner();
    }

    function applyFilter(inputName, inputCountry, inputState) {
        if (!inputName && !inputCountry && !inputState) {
            return;
        }

        $('.dealer-list').children().each(function(){
            var element = $(this);
            if (element.hasClass('dealer-item')) {
                element.removeClass('d-none');
                var name = element.find('.name-value')[0].innerHTML;
                if (name && inputName && !name.toLowerCase().includes(inputName.toLowerCase())) {
                    element.addClass('d-none');
                }
                var state = element.find('.state-value')[0].innerHTML;
                if (state != undefined && inputState != undefined && !state.toLowerCase().includes(inputState.toLowerCase())) {
                    element.addClass('d-none');
                }

                var country = element.find('.select-dealer').attr('data-market');
                if (country != undefined && inputCountry != undefined && !country.toLowerCase().includes(inputCountry.toLowerCase())) {
                    element.addClass('d-none');
                }
            }
        });
    }

    function clearDealers() {
       addSpinner('.preferred-dealers-list', 'top-30');
       $('.dealer-list').children().each(function() {
           $(this).removeClass('d-none');
       });
       $('.type-filter-model-name').val('');
       $('.type-filter-model-state').val('');
       $('.type-filter-model-country option[country-name="Market"]').attr('selected', 'selected');
       removeSpinner();
    }

    return {
        getDealerInfoObject: getDealerInfoObject,
        createPreferredDealerModalRow : createPreferredDealerModalRow,
        filterDealers: filterDealers,
        clearDealers: clearDealers
    };
})();

