function urgentRequestGetDealersList(productCode, urgentRequestButtons) {
    let url = getCurrentBaseUrl() + "p/urgentRequestDealersList";
    $.ajax({
        type: 'GET',
        url: url,
        data: {'productCode': productCode, 'isFromPDP': 'true'},
        contentType: "application/json",
        success: function(data) {
            let hasUrgentRequest = JSON.parse(data.hasUrgentRequest.toLowerCase());
            if (hasUrgentRequest) {
                $('body').append($(data.urgentRequestPopup));
                for (let i = 0; i < urgentRequestButtons.length; i++)    {
                    urgentRequestButtons[i].removeAttribute("disabled");
                    urgentRequestButtons[i].classList.remove("btn");
                    urgentRequestButtons[i].classList.remove("btn-primary-disabled");
                    urgentRequestButtons[i].textContent = data.urgentRequestLabel;
                }
            }
        },
        error: function(err) {
            console.log(err);
        }
    });
}

