function EquipmentTabDesktop() {
    const tabListPDP = $('#desktop-tablist-pdp').find('.nav-link');
    tabListPDP.each(function (i, obj) {
       const isFitmentTab = $(obj).attr('aria-label') == 'EQUIPMENT FITMENT';
       const isActiveTab = $(obj).hasClass('active');

       if (isActiveTab && !isFitmentTab) {
            $(obj).removeClass('active');
            $('#desktop-tablist-pdp').find('.tab-pane').removeClass('active show');
       }
       if (isFitmentTab && !isActiveTab) {
          $(obj).addClass('active');
          $('#desktop-tablist-pdp').find('#equipment-fitment').addClass('active show');
       }
    });
}

function EquipmentTabMobile() {
    const tabListPDPMobile = $('#pdp-tabs-section').find('.accordion').find('.card');
    tabListPDPMobile.each(function (i, obj) {
        const isFitmentTab = $(obj).find('.card-header').attr('id') == 'equipment-fitment';
        const isActiveTab = $(obj).hasClass('expanded');
        const ariaBtn = $(obj).find('.card-header').find('.btn');
        const ariaFitment = $(obj).find('.card-header').find('.btn');
        if (isActiveTab && !isFitmentTab) {
            $(obj).removeClass('expanded');
            $(obj).find('#collapse-equipment-fitment').removeClass('show');
            ariaFitment.each(function (i,ob) {
                 ob.setAttribute('aria-expanded', "false");
            });
        }
        if (isFitmentTab && !isActiveTab) {
          $(obj).addClass('expanded');
          $(obj).find('#collapse-equipment-fitment').addClass('show');
          ariaFitment.each(function (i,ob) {
               ob.setAttribute('aria-expanded', "true");
          });
        }
    });
}


