$(document).on("click", ".js-urgent-request-add-to-cart", function(event) {
    var partCode = [];
    let originalDealerCode = $(this).data('originalDealer');
    let selectedDealerCode = $(this).data('selectedDealer');
    let productCode = encodeURIComponent($(this).data('productCode'));
    let qtyElementId = $(this).data('productQtyElementId');
    let maxAvailableQty = $(this).data('maxQty');
    partCode.push(productCode);

    var url = getCurrentBaseUrl() + "validatePartFromCart?productCodes=" + partCode;
    $.ajax({
        type : 'GET',
        url : url,
        data: {
            'urgentRequestDealerCode': selectedDealerCode
        },
        success : function(data) {
            if (data.isAddToCart == "true") {
                let setDealerUrl = getCurrentBaseUrl() + "p/urgentRequestSetDealer";
                $.ajax({
                    type: 'POST',
                    url: setDealerUrl,
                    data: {
                        'urgentRequestDealerCode': selectedDealerCode,
                        'isUrgentRequest': true
                    },
                    success: function(data) {
                        addToCartPDP(qtyElementId, productCode, maxAvailableQty, '', originalDealerCode, true);
                    },
                    error: function(err) {
                        console.log(err);
                    }
                });
            }else if (data.isSameVendor == "true") {
                $('.js-modal-urgent-request').modal('hide');
                $('#modal-product-already-exist').modal('show');
            }else {
                $('body').append($(data.changeDealerInCartPopup));
                $('.js-modal-urgent-request').modal('hide');
                $('#modal-change-dealer').modal('show');
            }
        },
        error: function(e) {
            console.log(e);
        },
    });
});

$(document).on("click", ".js-urgent-request-update-quantity", function() {
    let element = document.getElementById($(this).data('targetElement'));
    let qty = parseInt($(element).val());
    let type = $(this).data('action');
    let maxProductsAvailable = parseInt($(this).data('maxQty'));
    let changeOfQuantity = parseInt($(this).data('qtyChange'));

    if (type === 'remove') {
        if (qty > changeOfQuantity) {
            qty = qty - changeOfQuantity; // DECREASE QUANTITY
        }

        if (qty == changeOfQuantity || maxProductsAvailable <= qty) {  // MIN QUANTITY SELECTABLE IS 1
            disableButton($(this));
        } else {
            enableButton($(this));
            enableButton($(this).parent().siblings(".quantity-add-urgent-request").find("button"));
        }
    } else if (type === 'add') {
        let newQty = qty + changeOfQuantity
        if (newQty <= maxProductsAvailable) {
            qty = newQty; // INCREASE QUANTITY
        }

        if (newQty >= maxProductsAvailable) { // MAX QUANTITY SELECTABLE IS THE MAX STOCK AVAILABILITY
            disableButton($(this));
        } else {
            enableButton($(this));
            enableButton($(this).parent().siblings(".quantity-remove-urgent-request").find("button"));
        }
    }
    let result = Math.max(1, qty);

    $('.'+$(this).data('targetElement')).each(function(){
        $(this).val(result);
    })
});

// Validate Product in Cart
function validatePartFromCartPDP(qtyElementId, maxAvailableQty, isPunchoutSession) {
    var partCode = [];
    let productCode = $(".add-to-cart-pdp").attr('data-product-code');
    let subOwnershipStock = $(".add-to-cart-pdp").attr('data-subownership-stock');
    let cspsStock = $(".add-to-cart-pdp").attr('data-dealer-stock-quantity');
    var encodedProductCode = encodeURIComponent(productCode);

    partCode.push(encodedProductCode);

    let button = $(event.target);
    const productStock = {
      subOwnershipStock: subOwnershipStock,
      cspsStock: cspsStock,
    };
    button.addClass('add-to-cart-button');
    button.prop('disabled',true);
    var url = getCurrentBaseUrl() + "validatePartFromCart?productCodes=" + partCode;
    $.ajax({
        type : 'GET',
        url : url,
        data: {
            'urgentRequestDealerCode': null
        },
        success : function(data) {


            if (data.isAddToCart == "true") {
                addToCartPDP(qtyElementId, encodedProductCode, maxAvailableQty, isPunchoutSession, '', '', '', productStock);
            }else if (data.isSameVendor == "true") {
                $('#modal-product-already-exist').modal('show');
                $('.add-to-cart-button').prop('disabled',false);
                enableAssemblyCartButton();
                removeSpinner();
            }else {
                $('body').append($(data.changeDealerInCartPopup));
                $('#modal-change-dealer').modal('show');
                $('.add-to-cart-button').prop('disabled',false);
                enableAssemblyCartButton();
                removeSpinner();
            }
        },
        error: function(e) {
            console.log(e);
        },
    });
};

function enableAssemblyCartButton()
{
    let buttonClass = sessionStorage.getItem('assembly-add-to-cart-id');
    if(buttonClass != undefined)
    {
        $(buttonClass).removeClass('disabled');
        sessionStorage.removeItem('assembly-add-to-cart-id');
    }
}

