function validatePartFromCartPLP(type, categoryGtm, assemblyProductCode) {
	let isEuSite = $(".product-part.product-list-serialNumber").attr('data-isEuSite');
	let anonymous= $(".product-part.product-list-serialNumber").attr('data-anonymous');
	var encodedAssemblyCode = encodeURIComponent(assemblyProductCode);
	var qty = $("#changeOfQuantity_" + getEncodedProductCode(assemblyProductCode)).val();
    localStorage.setItem("categoryGtm", categoryGtm);

	if (isEuSite == 'true' && anonymous=='true') {
		$('#showModalLoginEu').modal('show');
	}else {
        var $result = $('.js-add-selected-parts.selected').find('.js-selected-input');
        var productCodes = [];

        if(encodedAssemblyCode === '') {
            for (var i = 0; i < $result.length; i++) {
                var res = $($result[i]).attr('id');
                var productCode = encodeURIComponent($($result[i]).data("product-code"));
                productCodes.push(productCode);
            }
        } else {
            productCodes.push(encodedAssemblyCode);
        }

        var url = getCurrentBaseUrl() + "validatePartFromCart?productCodes=" + productCodes;
        $.ajax({
            type : 'GET',
            url : url,
            data: {
                'urgentRequestDealerCode': null
            },
            success : function(data) {
                var partsAlreadyInCart = data.partsAlreadyInCart.slice(1, -1).split(',').map(item=>item.trim());

                for (var i = $result.length-1; i >= 0; i--) {
                    var productCode = $($result[i]).data("product-code").toString();
                    if (partsAlreadyInCart.includes(productCode)) {
                        $result.splice(i, 1);
                        localStorage.setItem("somePartAreAlreadyInCart", true);
                    }
                };

                if (data.isAddToCart == "true" && assemblyProductCode !== "") {
                    addToCartPLPAssembly(encodedAssemblyCode, qty);
                }else if (data.isSameVendor == "true" && assemblyProductCode === "" && $result.length !== 0) {
                    addToCartPLP(type, $result, true, "", multiplePartsAssembly);
                }else if (data.isSameVendor == "true" && assemblyProductCode === "" && $result.length === 0) {
                     $('#somePartsAlreadyInCartPopup').find('.text-center').text($('#somePartsAlreadyInCartPopup').find('#modal-assembly-parts-are-already-cart').val());
                     $('#somePartsAlreadyInCartPopup').modal('show');
                }else if (data.isSameVendor == "true" && $result.length === 0) {
                    $('#partsAlreadyInCartPopup').modal('show');
                }else if (data.isSameVendor == "false" && $result.length !== 0) {
                    addToCartPLP(type, $result, true, true, "");
                    $('body').append($(data.changeDealerInCartPopup));
                    $('#modal-change-dealer').modal('show');
                }else {
                    $('body').append($(data.changeDealerInCartPopup));
                    $('#modal-change-dealer').modal('show');
                }
            },
            error: function(e) {
                console.log(e);
            },
        });
    }
};

