async function validatePartFromCartQuickOrder() {
	var checkedProducts = $(".checkbox_desktop.form-check-input:checked");
    var productCodes = [];
    
    for (var m = 0; m < checkedProducts.length; m++) {
        var productCode = encodeURIComponent(checkedProducts[m].id);
        productCodes.push(productCode);
    };

    var url = getCurrentBaseUrl() + "validatePartFromCart?productCodes=" + productCodes;
	$.ajax({
        type : 'GET',
        url : url,
        data: {
            'urgentRequestDealerCode': null
        },
        success : async function(data) {
            if(data.partsAlreadyInCart != "[]")
            {
                let partsAlreadyInCart = data.partsAlreadyInCart.slice(1, -1).split(',').map(item=>item.trim());

                for (var i = checkedProducts.length-1; i >= 0; i--) {
                    var productCode = checkedProducts[i].id;
                    if (partsAlreadyInCart.includes(productCode)) {
                        checkedProducts.splice(i, 1);
                    }
                };
            }
                if (data.isAddToCart == "true") {
                    await quickOrderAddToCartV2(checkedProducts)
                }else if (data.isSameVendor == "true" && checkedProducts.length !== 0) {
                    await quickOrderAddToCartV2(checkedProducts,true)
                }else if (data.isSameVendor == "true" && checkedProducts.length === 0) {
                    $('#partsAlreadyInCartPopup').modal('show');
                }else if (data.isSameVendor == "false" && checkedProducts.length !== 0) {
                    quickOrderAddToCartV2(checkedProducts, true, true);
                    $('body').append($(data.changeDealerInCartPopup));
                    $('#modal-change-dealer').modal('show');
                }else {
                    $('body').append($(data.changeDealerInCartPopup));
                    $('#modal-change-dealer').modal('show');
                }

            removeSpinner();
        },
        error: function(e) {
            console.log(e)
        },
    });
};

function addToCartQuickOrderData()
{
    var checkedProducts = $(".checkbox_desktop.form-check-input:checked").parent().parent().parent();
    let gtmGlobalData = parseGTMJsonData($('#gtmGlobalDataJson').html());
    var currentBrand = gtmGlobalData.sessionBrand.toUpperCase();
    const items = checkedProducts.map(function() {
        var productName = $(this).find('.quick-order-product-name').text();
        var productCode = $(this).find('.quick-order-product-code').text().replace('#','');
        var productPrice = $(this).find('.quick-order-product-price').data('product-price');
        var ItemCategory = $(this).data('item-category') !== undefined ? $(this).data('item-category') : '';
        var ItemCategory2 = $(this).data('item-category2') !== undefined ? $(this).data('item-category2') : '';

        return {
            "item_id": productCode,
            "item_name": currentBrand + ' | ' + productName,
            "affiliation": "My CNHI Store",
            "currency": gtmGlobalData.storeCurrency,
            "item_brand": currentBrand,
            "item_category": ItemCategory,
            "item_category2": ItemCategory2,
            "price": parseFloat(productPrice),
            "quantity": 1
        }
    }).get();

    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({
          "event": "add_to_cart",
          "category": "quick_order",
          "ecommerce": {
          "items":  items
          }
    });
}

function validatePartFromCartBulkWishlist(wishlistName) {
	var wishlist = document.getElementById(wishlistName);
	var wishlistProducts = $(wishlist).find(".product-wishlist-element");

    var productCodes = [];

    for (var i = 0; i < wishlistProducts.length; i++) {
        var productCode = encodeURIComponent($(wishlistProducts[i]).find('input[name="productCode"]').val());
        productCodes.push(productCode);
    };

    var url = getCurrentBaseUrl() + "validatePartFromCart?productCodes=" + productCodes;
	$.ajax({
        type : 'GET',
        url : url,
        data: {
            'urgentRequestDealerCode': null
        },
        success : function(data) {
            var partsAlreadyInCart = data.partsAlreadyInCart.slice(1, -1).split(',').map(item=>item.trim());

            for (var i = wishlistProducts.length-1; i >= 0; i--) {
                var productCode = $(wishlistProducts[i]).find('input[name="productCode"]').val();
                if (partsAlreadyInCart.includes(productCode)) {
                    wishlistProducts.splice(i, 1);
                }
            };

            if (data.isAddToCart == "true") {
                bulkAddToCartWishlist(wishlistProducts);
            }else if (data.isSameVendor == "true" && wishlistProducts.length !== 0) {
                bulkAddToCartWishlist(wishlistProducts, true);
            }else if (data.isSameVendor == "true" && wishlistProducts.length === 0) {
                $('#partsAlreadyInCartPopup').modal('show');
            }else if (data.isSameVendor == "false" && wishlistProducts.length !== 0) {
                bulkAddToCartWishlist(wishlistProducts, true, true);
                $('body').append($(data.changeDealerInCartPopup));
                $('#modal-change-dealer').modal('show');
            }else {
                $('body').append($(data.changeDealerInCartPopup));
                $('#modal-change-dealer').modal('show');
            }
        },
        error: function(e) {
            console.log(e);
        },
    });
}

