$(document).on("click", "#requestQuotationButton", function(event) {
    event.preventDefault();
    let comment = $('#quotation-request-text-area-id').val();
    let quotePhoneNumber = $('#quotePhoneNumber').val();
    let labourRequested = $('#requestServiceCheckbox').is(':checked');
    let laborRequestEquipment = labourRequested ? $('#requestlabourEquipment').val() : '';
    if (comment === '' || quotePhoneNumber === '' || (labourRequested && laborRequestEquipment === '')) {
        if (comment === '') {
            $("#errorMessage").removeClass('d-none');
        }
        if (quotePhoneNumber === '') {
            $("#phoneErrorMessage").removeClass('d-none');
        }
        if (labourRequested && laborRequestEquipment === '') {
            $("#labourErrorMessage").removeClass('d-none');
        }
        return;
    }

    $(this).addClass('disabled');

    window.location.href = actionUrl + "?comment=" + encodeURIComponent(comment) + "&phoneNumber=" + encodeURIComponent(quotePhoneNumber)
     + "&isLabourRequested=" + encodeURIComponent(labourRequested) + "&labourEquipment=" + encodeURIComponent(laborRequestEquipment);
});

