document.addEventListener('DOMContentLoaded', function () {
    (function () {
        var $body = $('body');
        if ($body.hasClass('page-homepage')) {
            if($('#countrySite').val() == 'CA' || $('#countrySite').val() == 'US'){
                $('.js-banner-url').each(function () {
                    var url = new URL(window.location.href);
                    var url_new = url.origin + url.pathname;
                    var href = $(this).attr('href');
                    if(!url_new.endsWith('/')){
                       url_new = url_new + '/';
                    }

                    if(!isValidURL(href)){
                       if(!href.startsWith('/')){
                            $(this).attr('href', url_new + href);
                       }
                    }
                });

            }

        }
    })();
    (function () {
        const tabListPDP = $('#desktop-tablist-pdp').find('.nav-item');
        const isBundleProduct = $('#desktop-tablist-pdp').find('#pdpTablist-navbar').data('product-information');
        const isStructuredProduct = $('#desktop-tablist-pdp').find('#pdpTablist-navbar').data('product-structure');
        const isEmptyTabs = $('#desktop-tablist-pdp').find('#pdpTablist-navbar').data('empty-tabs');

        tabListPDP.each(function (i, obj) {

         const isStructure =  $(obj).find('.nav-link').attr('href') == '#kit-structure';
         const isInfo=  $(obj).find('.nav-link').attr('href') == '#bundle-structure';
             if(isEmptyTabs) {
                if(isInfo || isStructure) {
                    $(obj).addClass('d-none');
                }
             }else if (isBundleProduct && isStructuredProduct) {
                if(isInfo || isStructure) {
                    $(obj).removeClass('d-none');
                }
             }else {
                if(!isBundleProduct && isInfo) {
                 $(obj).addClass('d-none');
                }
                if(isBundleProduct && isStructure) {
                 $(obj).addClass('d-none');
                }
             }
        });
        /* For mobile */
        const tabListPDPMobile = $('#tab-list-info-main').find('.card');
        tabListPDPMobile.each(function (i, obj) {

         const isStructure =  $(obj).find('.card-header').attr('id') == 'kit-structure';
         const isInfo =  $(obj).find('.card-header').attr('id') == 'bundle-structure';
            if(isEmptyTabs) {
                if(isInfo || isStructure) {
                    $(obj).addClass('d-none');
                }
            } else if (isBundleProduct && isStructuredProduct) {
                if(isInfo || isStructure) {
                    $(obj).removeClass('d-none');
                }
            }else {
                if(!isBundleProduct && isInfo) {
                 $(obj).addClass('d-none');
                }
                if(isBundleProduct && isStructure) {
                 $(obj).addClass('d-none');
                }
            }
        });
    })();
});

function isValidURL(string) {
    var res = string.match(/(http(s)?:\/\/.)?(www\.)?[-a-zA-Z0-9@:%._\+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_\+.~#?&//=]*)/g);
    return (res !== null)
};

