function callContractDealerModal() {
    const brandCode = localStorage.getItem("personalAreaBrandCode") || document.getElementById('hiddenBrandCode')?.value || '';

    return $.ajax({
        url: getCurrentBaseUrl() + 'dealers-by-contract',
        method: 'GET',
        data: { brandCode },
        success: function (list) {
            const $container = $('#dealers-by-contract-container');
            const $template = $('#dealers-by-contract-template');
            $container.empty();

            const $mobileContainer = $('#dealer-mobile-container');
            const $mobileTemplate = $('#dealer-mobile-template');
            $mobileContainer.empty();

            list.forEach(vendor => {
                const $clone = $template.clone().removeAttr('id').removeClass('d-none');
                $clone.find('.js-contract-dealer-name').text(vendor.name || '');
                $clone.find('.js-contract-dealer-town').text(vendor.address?.town || '');
                $clone.find('.js-contract-dealer-isocode').text(vendor.address?.region?.isocodeShort || vendor.address?.province || '');
                $clone.find('.js-contract-dealer-postal-code').text(vendor.address?.postalCode || '');
                $clone.find('.js-contract-dealer-phone').text(vendor.address?.phone || '');
                $clone.find('.js-contract-dealer-code').val(vendor.code || '');

                const $button = $clone.find('.select-dealer-popup');
                $button.attr('data-dealer-code', vendor.code || '')
                       .attr('data-gdd-code', vendor.gddCode || '')
                       .attr('data-brand-code', brandCode)
                       .attr('onclick', 'confirmDealerSelection(this)');

                $container.append($clone);

                const $mobileClone = $mobileTemplate.clone().removeAttr('id').removeClass('d-none');
                $mobileClone.find('.js-label-city').text('City');
                $mobileClone.find('.js-label-state').text('State');
                $mobileClone.find('.js-label-zip').text('ZIP');
                $mobileClone.find('.js-label-phone').text('Phone');

                $mobileClone.find('.js-dealer-name').text(vendor.name || '');
                $mobileClone.find('.js-dealer-town').text(vendor.address?.town || '');
                $mobileClone.find('.js-dealer-region').text(vendor.address?.region?.isocodeShort || vendor.address?.province || '');
                $mobileClone.find('.js-dealer-zip').text(vendor.address?.postalCode || '');
                $mobileClone.find('.js-dealer-phone').text(vendor.address?.phone || '');
                $mobileClone.find('.js-dealer-code').val(vendor.code || '');

                const $mobileButton = $mobileClone.find('.select-dealer-popup');
                $mobileButton.attr('data-dealer-code', vendor.code || '')
                             .attr('data-gdd-code', vendor.gddCode || '')
                             .attr('data-brand-code', brandCode)
                             .attr('onclick', 'confirmDealerSelection(this)');

                $mobileContainer.append($mobileClone);
            });
        },
        error: function (xhr, status, error) {
            console.error('Failed to load vendor list:', error);
        }
    });
}

