function serializeFiltersArray(target, required) {
    var requiredInput = $(target).find(required);

    if (requiredInput.length > 0) {
        if ($(target).find(required).filter(function () {
            return $.trim($(this).val()).length === 0;
        }).length == 0) {
            return $(target).find("input ,select").serializeArray();
        } else {
            return false;
        }
    } else if ($(target).find("input ,select").filter(function () {
        return $.trim($(this).val()).length > 0;
    }).length == 0) {
        return false;
    } else {
        return $(target).find("input ,select").serialize();
    }
};



