function enableSearchButton(_this, buttonSelector, minLengthSearch) {
	var $searchText = $(_this);
	if ($searchText.length > 0) {
		var len = $searchText.val().length;
		if (len >= minLengthSearch) {
			$(buttonSelector).removeClass("disabled");
		}
		else {
			$(buttonSelector).addClass("disabled");
		}
	}
}


//Sort by score DESC, part number ASC, assemblyFullName ASC
function sortPartsNumber(rows) {
	if (rows) {
		rows.sort(
			function(a, b) {
				if (a.partNumber === b.partNumber) {
					if (a.assemblyFullName === b.assemblyFullName) {
						return a.score < b.score ? 1 : -1;
					}
					var firstRow = (b.assemblyFullName).replace(/[\[\]']+/g, '!').replace(/\s/g, '\""');
					var secondRow = (a.assemblyFullName).replace(/[\[\]']+/g, '!').replace(/\s/g, '\""');
					return firstRow < secondRow ? 1 : -1;
				}
				return a.partNumber > b.partNumber ? 1 : -1;
			});
	}
	return rows;
}

//Sort by modelFullName ASC, part number ASC, assemblyFullName ASC, score DESC
function sortPartsNumberExpanded(rows) {
	if (rows) {
		rows.sort(
			function(a, b) {
				if (a.modelFullName === b.modelFullName) {
					if (a.partNumber === b.partNumber) {
						if (a.assemblyFullName === b.assemblyFullName) {
							return a.score < b.score ? 1 : -1;
						}
						var firstRow = (b.assemblyFullName).replace(/[\[\]']+/g, '!').replace(/\s/g, '\""');
						var secondRow = (a.assemblyFullName).replace(/[\[\]']+/g, '!').replace(/\s/g, '\""');
						return firstRow < secondRow ? 1 : (firstRow > secondRow ? -1 : 0);
					}
					return a.partNumber > b.partNumber ? 1 : -1;
				}
				return (b.modelFullName) < (a.modelFullName) ? 1 : ((b.modelFullName) > (a.modelFullName) ? -1 : 0);
			});
	}
	return rows;
}

//Sort by score DESC, part description ASC, assemblyFullName ASC
function sortPartsDescription(rows) {
	if (rows) {
		rows.sort(
			function(a, b) {
				if (a.score === b.score) {
					if (a.partDescription === b.partDescription) {
						return b.assemblyFullName - a.assemblyFullName;
					}
					return a.partDescription > b.partDescription ? 1 : -1;
				}
				return a.score < b.score ? 1 : -1;
			});
	}
	return rows;
}

//Sort by score DESC, assemblyFullName ASC
function sortFigures(rows) {
	if (rows) {
		rows.sort(
			function(a, b) {
				if (a.assemblyFullName === b.assemblyFullName) {
					let aVal = Object.values(eval(JSON.parse(a.functionalGroup)));
					let bVal = Object.values(eval(JSON.parse(b.functionalGroup)));
					if (aVal[0] === bVal[0]) {
						return a.score < b.score ? 1 : -1;
					}
					return aVal[0] > bVal[0] ? 1 : -1;
				}
				var firstRow = (b.assemblyFullName).replace(/[\[\]']+/g, '!').replace(/\s/g, '\""');
				var secondRow = (a.assemblyFullName).replace(/[\[\]']+/g, '!').replace(/\s/g, '\""');
				return firstRow < secondRow ? 1 : -1;
			});
	}
	return rows;
}

//Sort by modelFullName ASC, assemblyFullName ASC, functionGroup(section) ASC, score DESC
function sortFiguresExpanded(rows) {
	if (rows) {
		rows.sort(
			function(a, b) {
				var sectionA = getSectionFromFunctionGroup(a.functionalGroup);
				var sectionB = getSectionFromFunctionGroup(b.functionalGroup);

				if (a.modelFullName === b.modelFullName) {
					if (a.assemblyFullName === b.assemblyFullName) {
						if (sectionA === sectionB) {
							return a.score < b.score ? 1 : -1;
						}
						return (sectionB) < (sectionA) ? 1 : ((sectionB) > (sectionA) ? -1 : 0);
					}
					var firstRow = (b.assemblyFullName).replace(/[\[\]']+/g, '!').replace(/\s/g, '\""');
					var secondRow = (a.assemblyFullName).replace(/[\[\]']+/g, '!').replace(/\s/g, '\""');
					return firstRow < secondRow ? 1 : (firstRow > secondRow ? -1 : 0);
				}
				return (b.modelFullName) < (a.modelFullName) ? 1 : ((b.modelFullName) > (a.modelFullName) ? -1 : 0);
			});
	}
	return rows;
}

const defaultHeightShaveSearchInModel = 40;

function bindSort() {
	$(".sorter").on('click', function() {

		var sortBy = $(this).data('sorting');
		var sortToggle = localStorage.getItem("simSortToggle");
		$('.personal-area-table-component__heading-sort-up').removeClass('active');
		$('.personal-area-table-component__heading-sort-down').removeClass('active');
		if((sortToggle !== undefined && sortToggle !== null && sortToggle !== '') || sortToggle==sortBy){
			if(sortToggle=='asc'){
				sortBy='desc';
				$(this).find('.personal-area-table-component__heading-sort-down').addClass('active');
			} else {
				sortBy='asc'
				$(this).find('.personal-area-table-component__heading-sort-up').addClass('active');
			}
		}
		localStorage.setItem("simSortToggle", sortBy);

		var sortTarget = $(this).data('sorting-target');

		sortList($(sortTarget), sortBy, "." + $(this).data('sorter') + "-value", $(this).data('date-format'));

		let hrefUrl = window.location.href;
		if (hrefUrl.indexOf('dc/searchInModel') > -1 || hrefUrl.indexOf('dc/variantPage') > -1) {
			sessionStorage.setItem('sortProductList',$(this).data('sorting')+'/'+$(this).data('sorter'));
		}
	});
}

function performSavedSortPnList(){
	let hrefUrl = window.location.href;

	if (hrefUrl.indexOf('dc/searchInModel') > -1 || hrefUrl.indexOf('dc/variantPage') > -1) {
		let savedSort = sessionStorage.getItem("sortProductList");
		if(savedSort !== undefined && savedSort !== null){
			let arr = savedSort.split("/");
			$('.sorter' + "[data-sorting='" + [arr[0]] + "'][data-sorter='" + [arr[1]] + "']").click();
			sessionStorage.removeItem("sortProductList");
		}
	}
}

