function addToCartGraphicDesignDataLayer()
{
    let gtmGlobalData = parseGTMJsonData($('#gtmGlobalDataJson').html());
    var $result = $('.product-list-container input[id*="checkbox"]:checked');
    var items = [];
    var categoryLabel = localStorage.getItem("categoryGtm");
    if (gtmGlobalData.euNaftaDataLayerEnabled && categoryLabel == "from_graphic_design")
    {

        for (var i = 0; i < $result.length; i++)
        {
            var res = $($result[i]).attr('id');
            var itemData = res.split('_');
            var id = itemData[1];
            var name = gtmGlobalData.sessionBrand.toUpperCase() + " | " + itemData[7];
            var category = itemData[9];
            var subCategory = itemData[10];
            var price = itemData[8];
            var qty = itemData[3];
            var item = {
                "item_id": id,
                "item_name": name,
                "affiliation": "My CNHI Store",
                "currency": gtmGlobalData.storeCurrency,
                "item_brand": gtmGlobalData.sessionBrand,
                "item_category": category,
                "item_category2": subCategory,
                "price": price,
                "quantity": qty
            };
            items.push(item);
        }
        window.dataLayer = window.dataLayer || [];
        window.dataLayer.push({
        "event": "add_to_cart",
        "category": categoryLabel,
        "ecommerce": {
            "items": items
        }
        });
    }
}

