$('.toggle-subcategories').on('click', function (event)
{
    var btnTextMore = $(this).attr('data-btn-text-more');
    var btnTextLess = $(this).attr('data-btn-text-less');

     if ($(this).parents('.element').find('.text-description').height() > $(this).parents('.element').find('.container-text').height())
     {
       event.stopPropagation();
       event.preventDefault();
       $(this).parents('.element').find('.container-text').removeClass('expanded');

          if (btnTextMore)
          {
            $(this).parents('.element').find('.toggle-subcategories').text(btnTextMore);
          }
          else
          {
            $(this).parents('.element').find('.toggle-subcategories').text('view more');
          }

     }
     else
     {
       event.stopPropagation();
       event.preventDefault();
       $(this).parents('.element').find('.container-text').addClass('expanded');

          if (btnTextLess)
          {
            $(this).parents('.element').find('.toggle-subcategories').text(btnTextLess);
          }
          else
          {
            $(this).parents('.element').find('.toggle-subcategories').text('view less');
          }
     }
});


