$("#request-product-availability-button").on("click", function(){
    var emailRegex = /^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
    var email = $('.input-request-product-availability-email').val();


    if(!emailRegex.test(email))
    {
        $('.request-product-availability-email-error-msg').removeClass('d-none');
    }
    else
    {
        $('.request-product-availability-email-error-msg').addClass('d-none');
        //ajax to set the email in session\
        requestProductAvailability();
         var customerEmail = $("#request-product-availability-customer-login-email").val();
         $("#request-product-availability-email").val(customerEmail);
    }
})

