function getNotifyMeUserEmail()
{
    let url = getCurrentBaseUrl() + 'p/notifyMeEmail'
    $.ajax({
        type : 'GET',
        url : url,
        success : function (email)
        {
            $('#request-product-availability-customer-login-email').val(email);
            $("#request-product-availability-email").val(email);
        },
        error : function(error){
            console.log(error);
        }
    })
}


function requestProductAvailability()
{
    var email = $("#request-product-availability-email").val();
    var product = $("#request-product-availability-email").data("requestproductavailability");
    var url = window.location.pathname + "/request-product-availability?email=" + email

    $.ajax({
        type : "POST" ,
        url : url ,
        dataType : "json" ,
        contentType : "application/json" ,
        success : function(result){
            if(result === "Success"){
                $('#request-product-availability-modal').modal('show');
            }
        },
        error : function(error){
            console.log(error);
        }
    })
}

