function sortPersonalAreaOrders(sortBy) {

	$.urlParam = function(name) {
		var results = new RegExp('[\?&]' + name + '=([^&#]*)').exec(window.location.href);
		if (results == null) {
			return null;
		} else {
			return results.length >= 2 ? results[1] : null;
		}
	}
	var urlParams = 'sort=' + sortBy;

	if ($.urlParam('byModel') != null) {
		urlParams += '&byModel=' + $.urlParam('byModel');
	}
	if ($.urlParam('text') != null) {
		urlParams += '&text=' + $.urlParam('text');
	}
	if ($.urlParam('pageSize') != null) {
		urlParams += '&pageSize=' + $.urlParam('pageSize');
	}
	if ($.urlParam('page') != null) {
		urlParams += '&page=' + $.urlParam('page');
	} else {
		urlParams += '&page=0';
	}
	if ($.urlParam('filter_product_code') != null) {
		urlParams += '&filter_product_code=' + $.urlParam('filter_product_code');
	}
	if ($.urlParam('q') != null) {
		urlParams += '&q=' + $.urlParam('q');
	}

	$(location).attr('href', window.location.origin + window.location.pathname + '?' + urlParams);
}

