// --- Home Page Model&Serial Search ------ //
$("#search-by-parts-serial-home").on("input", function(e) {
    var searchTerm = this.value;
    var minCharsBeforeRequest = $(this).attr("data-minCharsBeforeRequest");
    var autocompleteUrl = $(this).attr("data-autocompleteUrl");
    var searchBy = "1"; //search by model by default
	var waitTimeBeforeRequest = $(this).attr("data-waitTimeBeforeRequest");
	
    if ($('#serial').hasClass('btn-filled')) {
        searchBy = "2"; //search by serial
    }

    this.parentNode.className = "searchbar expanded-autocomplete";
    var ul = document.createElement("ul");
    ul.setAttribute('id','search-input-autocomplete-list');
    ul.setAttribute('class','autocomplete-items');
    closeAllLists();

	if (searchTerm != '' && searchTerm.length >= minCharsBeforeRequest) {
		if (requestTimer) {
			clearTimeout(requestTimer);
		}
		requestTimer = setTimeout(function() {
			if (searchRequest) {
				searchRequest.abort();
			};

			searchRequest = $.ajax({
				type: 'GET',
				url: autocompleteUrl,
				data: {
					term: searchTerm,
					byModel: searchBy
				},
				success: function(data) {
					if (searchBy == '1') {
						renderModelSuggestions(data, e.target.parentNode);
					} else {
						renderSerialSuggestions(data, e.target.parentNode);
					}

				},
				error: function(e) {
					console.log(e);
				}
			})
		}, waitTimeBeforeRequest);
	}
});

function checkModelSerialFromCustomer(byModel, searchText, searchUrl, e)
{
    const dontAskAgain = localStorage.getItem('dontAskAgain');
    const isPunchoutSiteSession = $("#punchoutSessionInput").val();

    if(dontAskAgain === 'true' || isPunchoutSiteSession === 'true')
    {
       window.location.href = searchUrl;
    }
    else
    {
        if (e)
        {
            e.preventDefault();
            e.stopPropagation();
        }
        let url = getCurrentBaseUrl() + 'search/checkModelSerialFromCustomer';

         $.ajax({
             type: "GET",
             url : url,
             data : {'byModel' : byModel, 'searchText' : searchText},
             contentType: "json",
             success : function (result)
             {
                 if (result === "true")
                 {
                    closeAllLists();
                   $('#save-model-modal').modal('show');
                   $('#save-model-modal').find('#no-btn-save-model').attr('data-url', searchUrl);
                   $('#save-model-modal').find('#yes-btn-save-model')
                        .attr('data-url', searchUrl)
                        .attr('data-bymodel', byModel)
                        .attr('data-searchtext', searchText);
                 }
                 else
                 {
                   window.location.href = searchUrl;
                 }

             },
             error: function (err)
             {
                console.log(err);
             }
         });
    }
}


    $('#yes-btn-save-model').on('click', function() {
        $('#save-model-modal').hide();
        const $button = $(this);
        const byModel = $button.data('bymodel');
        const searchText = $button.data('searchtext');
        const searchUrl = $('#no-btn-save-model').data('url');
        checkDontAskAgain();

        fetch(getCurrentBaseUrl() + 'search/saveVehicleCustomer', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded'
            },
            body: new URLSearchParams({
                byModel: byModel,
                searchText: searchText
            })
        })
        .then(response => {
            if (!response.ok)
            {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            window.location.href = searchUrl;
        })
        .catch(error => {
            console.error('Save vehicle failed:', error);
        });
    });

    $('#no-btn-save-model, #modal-save-model-search-close').on('click', function() {
        const searchUrl = $('#no-btn-save-model').data('url');
        $('#save-model-modal').hide();
        checkDontAskAgain();
        window.location.href = searchUrl;
    });

    $('#dont-ask-again-checkbox').on('change', function ()
    {
        $(this).toggleClass('selected', this.checked);
    });

function checkDontAskAgain()
{
    if($('#dont-ask-again-checkbox').hasClass('selected'))
    {
        localStorage.setItem('dontAskAgain', 'true');
    }
    else
    {
       localStorage.setItem('dontAskAgain', 'false');
    }
}

function removeCustomerSession()
{
     localStorage.removeItem('dontAskAgain');
}



