function renderModelSuggestions(modelSuggestions, container) {
    var models = modelSuggestions.categories;
    closeAllLists();
    var ul = document.createElement("ul");
    ul.setAttribute('id','search-input-autocomplete-list');
    ul.setAttribute('class','autocomplete-items');

    if (models && models.length > 0) {
        models.forEach(function (model) {
            ul.appendChild(createModelSuggestionEntry(model));
        });
        container.appendChild(ul);
    }
}

function createModelSuggestionEntry(category) {
    var currentUrl = getCurrentBaseUrl().substring(0, getCurrentBaseUrl().length - 1)
    var url = currentUrl + category.url + '?categorySearch=true&modelSerialSearch=true'
    var categoryName = category.fullName;
    var a = document.createElement('a');
    var type = categoryName;
    if(type.includes("'"))
    {
        type = type.replace(/'/g, "\\'");
    }
    var gtmSearchStart = "gtmSearchStartMenu('model','" + $('#search-by-parts-serial-home').val() + "','search_catalog','suggested search','" + type + "')";
    a.setAttribute('href', url);
    a.innerText = categoryName;
    var li = document.createElement('li');
    li.setAttribute('class','list-unstyled suggestion-items-redirect');
    li.setAttribute('id',category.code);
    li.setAttribute('onmouseover','mouseHover(this)');
    li.setAttribute('onmouseout','moveOut(this)');
    li.setAttribute(
      'onclick',
      "event.preventDefault(); " +
      gtmSearchStart +
      "; checkModelSerialFromCustomer('1','" + category.code + "', '" + url + "', event); return false;"
    );
    li.appendChild(a);
    return li;
}

function renderSerialSuggestions(serialSuggestions, container) {
    var serials = serialSuggestions.serialNumbers;
    closeAllLists();
    var ul = document.createElement("ul");
    ul.setAttribute('id','search-input-autocomplete-list');
    ul.setAttribute('class','autocomplete-items');

    if (serials && serials.length > 0) {
        serials.forEach(function (serial) {
            ul.appendChild(createSerialSuggestionEntry(serial, getSerialNumberDisplay(serial)));
        });
        container.appendChild(ul);
    }
}

function createSerialSuggestionEntry(serial, serialLabel) {
    var a = document.createElement('a');
    var currentUrl = getCurrentBaseUrl().substring(0, getCurrentBaseUrl().length - 1)
    var url = currentUrl + serial.url
    a.setAttribute('href', url);
    a.innerText = serialLabel;
    var type = serialLabel;
    if(type.includes("'"))
    {
        type = type.replace(/'/g, "\\'");
    }
    var gtmSearchStart = "gtmSearchStartMenu('serial','" + $('#search-by-parts-serial-home').val() + "','search_catalog','suggested search','" + type + "')";

    var li = document.createElement('li');
    li.setAttribute('class','list-unstyled suggestion-items-redirect');
    li.setAttribute('id',serial.serialNumberCode);
    li.setAttribute('onmouseover','mouseHover(this)');
    li.setAttribute('onmouseout','moveOut(this)');
        li.setAttribute(
          'onclick',
          "event.preventDefault(); " +
          gtmSearchStart +
          "; checkModelSerialFromCustomer('2','" + serial.serialNumberCode + "', '" + url + "', event); return false;"
        );
    li.appendChild(a);
    return li;
}

function getSerialNumberDisplay(serial) {
    var serialNumberDisplay = "";
    if (serial.serialNumberCode.length == 0 && serial.serialNumberPin.length == 0) {
        serialNumberDisplay = serial.modelFullName + ' ' + serial.modelDate;
    } else {
        serialNumberDisplay = getSerialNumberDisplayable(serial);
        serialNumberDisplay = serialNumberDisplay != '' ? serialNumberDisplay + ' - ' + serial.modelFullName : serial.modelFullName;
    }
    return serialNumberDisplay;
}

function getDisplayableSerialNumber(item){
	var $labelSerialNumber = $('.label-serial-number');
	var label = $labelSerialNumber.data('serial-number-displayable-label');
	var labelNoPin = $labelSerialNumber.data('serial-number-displayable-no-pin-label');
	var serialNumberCode;
	var serialNumberPin;
	if (item){
    	serialNumberCode= item.serialNumberCode;
    	serialNumberPin = item.serialNumberPin;
	}
	else{
		serialNumberCode = sessionStorage.getItem('serialNumberCode');
		serialNumberPin = sessionStorage.getItem('serialNumberPin');
	}
	return buildSerialNumberDisplayable(label, labelNoPin, serialNumberCode, serialNumberPin)
}

