$("#selectedEquipment").on("change",function (e) {
      addSpinner('body', 'top-20');
      var selectedItem = this.value;
        var baseUrl = getCurrentBaseUrl();
        var modelDropdown = document.getElementById("selectedModel");
        var mktDropdown = document.getElementById("selectedMktCategory");
        var textSearch = document.getElementById("search-by-model-input");
        var buttonSearch = document.getElementById("model-text-button-search");
        var buttonSearchMobile = document.getElementById("model-text-button-search-mobile");
        var options = [];
        var option = document.createElement("option");
        modelDropdown.options.length=1;
        disableAttributes(modelDropdown,mktDropdown,textSearch,buttonSearch, buttonSearchMobile);
            $.ajax({
                type : 'GET',
                url: baseUrl+'cn/populateModelDropDown',
                data: {"categoryCode" : selectedItem},
                success: function(data){
                     for (var i = 0; i < data.length; i++)
                     {
                         option.text = data[i];
                         option.value = data[i];
                         options.push(option.outerHTML);
                     }
                      if(data.length == 0)
                      {
                        closeAllLists(e);
                        disableAttributes(modelDropdown,mktDropdown,textSearch,buttonSearch, buttonSearchMobile);
                      }
                      else
                      {
                        modelDropdown.removeAttribute('disabled');
                      }
                    removeSpinner();
                    modelDropdown.insertAdjacentHTML('beforeEnd', options.join('\n'));


                },
                error: function(error){
                    console.log("fail");
                }
            });

 });

 function disableAttributes(modelDropdown,mktDropdown,textSearch,buttonSearch, buttonSearchMobile)
 {
    modelDropdown.setAttribute('disabled','');
    mktDropdown.setAttribute('disabled','');
    mktDropdown.options.length=1;
    textSearch.setAttribute('disabled','');
    textSearch.value="";
    enableGuidedSearchIcon(buttonSearch, buttonSearchMobile, false);
 }
 function enableGuidedSearchIcon(buttonSearch, buttonSearchMobile, toEnable)
 {
    var mktDropdown = document.getElementById("selectedMktCategory");
    if(toEnable == true || mktDropdown.value != '')
    {
        $("#".concat(buttonSearch.id)).removeClass("disabled");
        $("#".concat(buttonSearchMobile.id)).removeClass("disabled");
    }
    else
    {
        $("#".concat(buttonSearch.id)).addClass("disabled");
        $("#".concat(buttonSearchMobile.id)).addClass("disabled");
    }

 }


