//guided search autosuggest
var currentFocus=-1;
var searchRequest;
$("#search-by-model-input").on("input", function(e) {
	var textId = this;
	var val = textId.value;
	var baseUrl = getCurrentBaseUrl();
	var equipCode = $("#selectedEquipment").val();
	var modelCode = $("#selectedModel").val();
	var mktCode = $("#selectedMktCategory").val();
	var buttonSearch = document.getElementById("model-text-button-search");
	var buttonSearchMobile = document.getElementById("model-text-button-search-mobile");
	textId.parentNode.className = "input-container expanded-autocomplete";
	var ul = document.createElement("ul");
	ul.setAttribute('id', 'search-input-autocomplete-list');
	ul.setAttribute('class', 'autocomplete-items');

	var waitTimeBeforeRequest = $(this).attr("data-waitTimeBeforeRequest");

	closeAllLists();
	closeIconSearchGuided();
	enableGuidedSearchIcon(buttonSearch, buttonSearchMobile, false);
	if (val != '' && val.length >= 2) {
		if (requestTimer) {
			clearTimeout(requestTimer);
		}
		requestTimer = setTimeout(function() {
			enableGuidedSearchIcon(buttonSearch, buttonSearchMobile, true);
			if (searchRequest) {
				searchRequest.abort();
			};
			searchRequest = $.ajax({
				type: 'GET',
				url: baseUrl + 'search/autocompleteGuidedSearch',
				data: { "term": val, "mktCode": mktCode, "selectedModelCode": modelCode, "selectedEquipCode": equipCode },
				success: function(data) {
					var suggested = data.products;
					for (i = 0; i < suggested.length; i++) {
						var label = suggested[i].code.toUpperCase().concat(" - ").concat(suggested[i].name.toUpperCase());
						var prodUrl = baseUrl +  suggested[i].url.replace(/^\/+/, "") + "?selectedModelCode="+modelCode;
						var a = document.createElement('a');
						var type = label;
						if (type.includes("'")) {
							type = type.replace(/'/g, "\\'");
						}
						var gtmSearchStartSubMenu = "clickSearchStartSubMenu('suggested search','" + type + "')"
						a.setAttribute('href', prodUrl);
						a.innerText = label;
						var li = document.createElement('li');
						li.setAttribute('class', 'list-unstyled suggestion-items-redirect');
						li.setAttribute('id', suggested[i].code);
						li.setAttribute('onmouseover', 'mouseHover(this)');
						li.setAttribute('onmouseout', 'moveOut(this)');
						li.setAttribute('onclick', gtmSearchStartSubMenu);
						li.appendChild(a);
						ul.appendChild(li);
					}
					if (suggested.length > 0) {
						textId.classList.add("autocomplete-input");
						textId.parentNode.appendChild(ul);
					}
				},
				error: function(error) {
					console.log("fail");
				}
			})
		}, waitTimeBeforeRequest);
	}
});

