// -------- events for autosuggests start ---------------
function mouseHover(x) {
    removeAllHovered();
    document.getElementById(x.id).classList.add("hovered");
}
function moveOut(x) {
    document.getElementById(x.id).classList.remove("hovered");

}

function autoSuggestEvents(e, buttonSearch)
{
   var activeAutocompletList = document.getElementById("search-input-autocomplete-list");
     if(e.keyCode == 40)
     {
          currentFocus++;
          addActive(activeAutocompletList);
     }
     else if(e.keyCode == 38)
        {
            currentFocus--;
            addActive(activeAutocompletList);

        }
     else if(e.keyCode == 13)
     {
         e.preventDefault();
         if (currentFocus > -1 && activeAutocompletList.children.length > 0) {
           var currListItem = $("li.suggestion-items-redirect");
           currListItem[currentFocus].classList.remove("autocomplete-active");

           var anchor = currListItem.eq(currentFocus).find('a');
           anchor.trigger('click');
           if(buttonSearch !== 'search-by-model-button-icon-home')
           {
             window.location.href = anchor.attr('href');
           }
         }
         else if(currentFocus == -1)
         {
             document.getElementById(buttonSearch).click();
         }
     }
}
function removeAllHovered()
{
    currentFocus=-1;
    var x = document.getElementsByClassName("list-unstyled suggestion-items-redirect hovered");
    for (var i = 0; i < x.length; i++) {
        x[i].className = "list-unstyled suggestion-items-redirect";
    }
}
  function addActive(x)
  {
    if (!x) return false;
    removeActive(x);
    var element = x.childNodes;
    if (currentFocus >= element.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = (element.length - 1);
    element[currentFocus].classList.add("autocomplete-active");
    element[currentFocus].classList.add("keyboard-selected");
    element[currentFocus].classList.add("hovered");
  }
  function removeActive(x)
  {
    var element = x.childNodes;
    for (var i = 0; i < element.length; i++) {
      element[i].classList.remove("autocomplete-active");
      element[i].classList.remove("keyboard-selected");
      element[i].classList.remove("hovered");
    }
  }
  function closeAllLists(e)
  {
    currentFocus=-1;
    $(".autocomplete-items").remove();
  }

  document.addEventListener("click", function (e) {
      closeAllLists(e.target);
      closeIconSearchCombined();
      closeIconSearchGuided();
  });

//------events for autosuggests  end ---------------

async function fetchEquipmentFitmentData(productCode) {
    const recaptchaToken = await recaptcha.execute('equipment_fitment');
    return new Promise(function(resolve, reject) {
        $.ajax({
            type: 'POST',
            contentType: 'application/json',
            dataType: 'json',
            url: getCurrentBaseUrl() + 'p/' + productCode + '/equipmentFitment/models',
            data: JSON.stringify({ recaptchaToken: recaptchaToken }),
            success: function(data) {
                resolve(data);
            },
            error: function(xhr, status, error) {
                reject(error);
            }
        });
    });
}

$("#tab-equipment-fitment").on("click", function(e) {
    addSpinner('#equipment-fitment', 'top-50');
    var productCode = $('#tab-equipment-fitment').data('productcode');

    fetchEquipmentFitmentData(productCode)
        .then(function(data)
        {
            removeSpinner();
            $('.tabListSorterIdDesktop').empty().append($(data.forDesktop));
            if (data.forDesktop == "")
            {
                displayNoEquipmentFoundDesktop();
            }
        })
        .catch(function(error)
        {
            removeSpinner();
            displayNoEquipmentFoundDesktop();
            console.log("AJAX error:", error);
        });
});

function displayNoEquipmentFoundDesktop()
{
    $('#equipment-fitment').show();
    $('#fitment-preview-container').removeClass('d-lg-block').addClass('d-lg-none');
    $('.no-fitment-found').removeClass('d-none');
}

function clickAccordion(event, id)
{
    var toggleId = $('.toggle-icon-'+id);
    var modelCode = $('#collapse-parent-'+id+'-child-0').data('modelcode');

    if($(toggleId).hasClass('fa-chevron-down'))
    {
        $(toggleId).removeClass('fa-chevron-down');
        $(toggleId).addClass('fa-chevron-up');
        if($('.model-list-desktop-'+id).children().length == 1)
        {
            addSpinner('body', 'top-30')
            loadFigures(modelCode, id);
        }
    }
    else if($(toggleId).hasClass('fa-chevron-up'))
    {
        $(toggleId).removeClass('fa-chevron-up');
        $(toggleId).addClass('fa-chevron-down')
    }
}

async function clickAccordionMobile(event, id) {
    const toggleId = $('.toggle-icon-mobile-' + id);
    const modelList = $('.model-mobile-list-' + id);
    const modelCode = modelList.data('modelcode');
    const figure = $('.model-list-mobile-' + id).children().length;

    if (toggleId.hasClass('fa-chevron-down')) {
        if (figure === 0) {
            await loadFiguresForMobile(modelCode, id);
        }
        // Spinner removal moved inside the success and error callbacks of the AJAX request
        $(toggleId).toggleClass('fa-chevron-down fa-chevron-up');
        $('.mobile-figures-'+id).addClass('show');
        modelList.removeClass('collapsed');
        modelList.attr('aria-expanded', 'true');
    } else {
        $(toggleId).toggleClass('fa-chevron-up fa-chevron-down');
        $('.mobile-figures-'+id).removeClass('show');
        modelList.addClass('collapsed');
        modelList.attr('aria-expanded', 'false');
    }
}

async function loadFiguresForMobile(modelCode, id){
    addSpinner('body', 'top-30');
    const productCode = $('#tab-equipment-fitment').data('productcode');
    const modelLine = $(".model-list-mobile-" + id);
    try {
        const data = await $.ajax({
            type: 'GET',
            dataType: 'json',
            url: getCurrentBaseUrl() + 'p/' + productCode + '/equipmentFitment/figures/' + modelCode
        });
        modelLine.append(data.forMobile);
    } catch (error) {
        console.log("AJAX error:", error);
    } finally {
        removeSpinner();
    }
}

function loadFigures(modelCode, id){

    var productCode = $('#tab-equipment-fitment').data('productcode');
    var modelLine = $(".model-list-desktop-"+id);
    $.ajax({
        type: 'GET',
        dataType: 'json',
        url: getCurrentBaseUrl() + 'p/' + productCode + '/equipmentFitment/figures/' + modelCode,
        success: function(data) {
            removeSpinner();
            modelLine.append(data.forDesktop);
        },
        error: function(xhr, status, error) {
            removeSpinner();
            console.log("AJAX error:", error);
        }
    });
}



