async function clickNextAssembly(event)
{
    event.preventDefault();
    addSpinner('#equipment-fitment', 'top-50')
    var activeLi = $('.selected-li');
    if(activeLi.length > 0)
    {
        var listCount = $('.selected-li').parent().children('li').length
        var nextAssembly;
        if((listCount - 1) == activeLi.index())
        {
         nextAssembly = $('.selected-li').parent().children('li')[1]
        }
        else
        {
         nextAssembly = activeLi.next()
        }

        activeLi.removeClass('selected-li')

        var element = $(nextAssembly).children()[4];
        var modelCode = $(element).data('modelcode');
        var assemblyCode = $(element).data('assemblycode');
        var url = $(element).data('url');
        var productCode = $('#tab-equipment-fitment').data('productcode');
        var result = JSON.parse(await generateCanvasData(modelCode, assemblyCode));
        $.ajax({
                type: 'GET',
                dataType: 'json',
                url: getCurrentBaseUrl() + 'p/' + productCode + '/mini-assembly/'+assemblyCode+'/'+modelCode,
                success: function(data) {
                    removeSpinner()
                    $('#mini-assembly-container').remove()
                    $('#equipment-fitment').append($(data.miniAssemblyPage));
                    $('#hotspot-image').attr('src',url);
                    $(nextAssembly).addClass('selected-li')
                    callHotspotFunction(result, event);
                },
                error: function(xhr, status, error) {
                    console.log("AJAX error:", error);
                }
            });
    }

}

