async function registerUser(event){
    event.preventDefault();
    addSpinner(".main", "top-20");
    var registerBtn = $('#checkout-confirm-shipping');
    registerBtn.attr('disabled', true);
    registerBtn.addClass('disable-button');

    //Collect form data
    var formData = {
        firstName: $("input[name='first-name']").val(),
        lastName: $("input[name='last-name']").val(),
        email:$("input[name='email']").val(),
        pwd: $("input[name='password']").val(),
        checkPwd: $("input[name='password-confirm']").val(),
        termsCheck: true
    }

    var checkBoxes = document.querySelectorAll('input[id="privacy-checkbox-1"]');

    var policies = []
    var policy = {
        id: "",
        accepted: true
    }

    checkBoxes.forEach(function(checkbox) {
        var policy = { id: checkbox.name };
        if (checkbox.checked) {
            policy.accepted = true;
        } else {
            policy.accepted = false;
        }
        policies.push(policy);
    })

    var radioGroups = document.querySelectorAll('.radio-group');
        radioGroups.forEach(function(radioGroup) {
        // Get the group name from the data attribute
        var groupName = radioGroup.getAttribute('data-group');

        var policy = { id: groupName };

        // Get all the radio buttons in the current group
        var radioButtons = radioGroup.querySelectorAll('input[type="radio"]');

        var selectedValue = null;

        // Loop through the radio buttons and check which one is selected
        radioButtons.forEach(function(radioButton) {
            if (radioButton.checked) {
                selectedValue = radioButton.value;
            }
        });

        if (selectedValue == "accept") {
            policy.accepted = true;
        }
        else {
            policy.accepted = false;
        }

        policies.push(policy);
    });

    var recaptchaToken = await recaptcha.execute('signup');

    var message = {
        formData: formData,
        policies: policies,
        recaptchaToken: recaptchaToken
    };

    var jsonData = JSON.stringify(message);

    var currentUrl = window.location.href;
    var getUrl = currentUrl + '/newcustomer'
    //Send the data to your server using ajax
    $.ajax({
        type: 'POST',
        url: getUrl, // Use the URL of your controller action
        data: jsonData,
        contentType: "application/json",
        success:function(xhr, status, data){
            // Handle the success response
           /* let hideSection = $("#hideThisSection");
            let showSection = $("#showThisSection");
            // Hide this if the register is success
            hideSection.attr("data-trigger-registration","hide");
            hideSection.addClass("d-none");
            // Show Success page section
            showSection.attr("data-trigger-registration","show");
            showSection.removeClass("d-none");*/

          if(status === "success") {
                location.href = currentUrl + "/success";
                var category = localStorage.getItem("loginDialogLabel");
                 let gtmGlobalData = parseGTMJsonData($('#gtmGlobalDataJson').html());
                if (gtmGlobalData.euNaftaDataLayerEnabled)
                {
                window.dataLayer = window.dataLayer || [];
                window.dataLayer.push({
                    "event": "sign_up",
                    "category": category
                });
                }
            }
        },
        error:function(xhr, status, error){
            //handle errors
            let serverErrorCode = xhr.status;
            if (serverErrorCode === 409) {
                $(".userAlreadyExist").removeClass("d-none");
            } else if (serverErrorCode === 417) {
                $(".regFailed").removeClass("d-none");
            }
            removeSpinner();
            registerBtn.removeClass('disable-button');
            registerBtn.attr('disabled', false);
        }
    })
}

