function gtmSearchStartMainCategory(categoryName, categoryUrl){
    let gtmGlobalData = parseGTMJsonData($('#gtmGlobalDataJson').html());

    if (gtmGlobalData.euNaftaDataLayerEnabled)
    {
        let combinedSearchTerm = "text";
        let marketingCategorySearchTerm = "cn/";
        let label = "";
        let action = categoryName;

        var categoryVal = "Category menu";

        localStorage.setItem("mainCategoryName", action);
        localStorage.setItem("noSearchResultCategory", categoryVal);

        if (categoryUrl.includes(combinedSearchTerm))
        {
            const urlParams = new URLSearchParams(categoryUrl);
            label = urlParams.get('text');

            localStorage.setItem("mainCategoryLabel", label);

            window.dataLayer = window.dataLayer || [];
            window.dataLayer.push({
              "event": "search_start_category",
              "category": categoryVal,
              "action": action.toLowerCase(),
              "label": label.toLowerCase()
            });
        }
        else if (categoryUrl.includes(marketingCategorySearchTerm))
        {
            let index = categoryUrl.lastIndexOf(marketingCategorySearchTerm);
            let marketingCategoryCode = categoryUrl.slice(index+marketingCategorySearchTerm.length);

            getMarketingCategoryName(marketingCategoryCode)
                .then(function(data)
                {
                    label = data.toLowerCase();

                    localStorage.setItem("mainCategoryLabel", label);

                    window.dataLayer = window.dataLayer || [];
                    window.dataLayer.push({
                      "event": "search_start_category",
                      "category": categoryVal,
                      "action": action.toLowerCase(),
                      "label": label.toLowerCase()
                    });
                })
                .catch(function(error)
                {
                    console.log("Error occurred while retrieving category name:", error);
                });
        }
        else
        {
            localStorage.setItem("searchStartMainCategoryNonPlp", true);

            window.dataLayer = window.dataLayer || [];
            window.dataLayer.push({
              "event": "search_start_category",
              "category": categoryVal,
              "action": action.toLowerCase()
            });
        }
    }
}

