function gtmSearchStartMenu(category,action,menu,option,type){
    let gtmGlobalData = parseGTMJsonData($('#gtmGlobalDataJson').html());
        if (gtmGlobalData.euNaftaDataLayerEnabled)
        {
             var categoryVal = '';
             var searchPartsCatalog = 'true';

             if (category === 'equipment') {

                 window.dataLayer = window.dataLayer || [];
                 window.dataLayer.push({
                     event: "search_start_menu",
                     label: menu
                 });
                 return;
             }

             if (category === 'partium')
             {
                 categoryVal = 'partium';
                 let normalizedAction = (action || '').toLowerCase();
                 localStorage.setItem("searchStartActionPartium", normalizedAction);
                 window.dataLayer = window.dataLayer || [];
                 window.dataLayer.push({
                     event: "search_start_menu",
                     category: categoryVal,
                     action: normalizedAction,
                     label: "partium_search"
                 });

                 return;
             }

             switch(category)
                 {
                   case 'all':
                     categoryVal = "keyword / part number";
                     localStorage.setItem("searchStartLabel", menu);
                     localStorage.setItem("searchStartAction", action);
                     localStorage.setItem("searchStartCategory", categoryVal);
                     localStorage.setItem("noSearchResultCategory", categoryVal);
                     break;
                   case 'model':
                     categoryVal = "Model";
                     localStorage.setItem("searchStartLabel", menu);
                     localStorage.setItem("searchStartAction", action);
                     localStorage.setItem("searchStartCategory", categoryVal);
                     localStorage.setItem("searchPartsCatalog", searchPartsCatalog);
                     localStorage.setItem("noSearchResultCategory", categoryVal);
                     break;
                   case 'serial':
                   default:
                     categoryVal = "Serial number";
                     localStorage.setItem("searchStartLabel", menu);
                     localStorage.setItem("searchStartAction", action);
                     localStorage.setItem("searchStartCategory", categoryVal);
                     localStorage.setItem("searchPartsCatalog", searchPartsCatalog);
                     localStorage.setItem("noSearchResultCategory", categoryVal);
                 }

                 if (type !== null && type !== undefined)
                 {
                     localStorage.setItem("optionActionSelected", type);
                 }
                 else
                 {
                     localStorage.removeItem("optionActionSelected");
                 }

             window.dataLayer = window.dataLayer || [];
             if(type != null)
             {
                 window.dataLayer.push({
                     "event": "search_start_menu",
                     "category": categoryVal,
                     "action": action,
                     "label": menu,
                     "option": option,
                     "type": type
                 });
             }
             else
             {
                 window.dataLayer.push({
                    "event": "search_start_menu",
                     "category": categoryVal,
                    "action": action,
                    "label": menu,
                    "option": option
                 });
             }
        }
}

