// Current code (isInUseQuantity) expects that the PDP qty never exceeds the max stock set in the input element.
$('#qty-cnt-pdp').on('blur', function () {
    var changeOfQuantity = parseInt($(this).data('quantityStep'));
    var parsedInputQty = parseInt($(this).val());
    var productStock = parseInt($(this).attr('max'));

    if (!parsedInputQty || parsedInputQty <= 0) {
        $(this).val(changeOfQuantity);
    } else {
        if (parsedInputQty > productStock)  {
            var maxInputPackQty = Math.floor(productStock / changeOfQuantity) * changeOfQuantity;
            if (maxInputPackQty <= 0)   {
                $(this).val(changeOfQuantity);
            } else  {
                $(this).val(maxInputPackQty);
            }
        } else  {
            var roundedUpInputPackQty = Math.ceil(parsedInputQty / changeOfQuantity) * changeOfQuantity;
            if (roundedUpInputPackQty <= productStock)  {
                $(this).val(roundedUpInputPackQty);
            } else  {
                var maxInputPackQty = Math.floor(productStock / changeOfQuantity) * changeOfQuantity;
                $(this).val(maxInputPackQty);
            }
        }
    }
});

