async function loadStocks() {
    let $container = $('.js-product-carousel-stock');

     let productCodes = $container.map(function () {
             let href = $(this).data('href');
             return href ? href.split('/').filter(Boolean).pop() : null;
         })
         .get();

    if (productCodes.length === 0) {return}

    let url = getCurrentBaseUrl() + "async/product-carousel/populateStocks?productCodes=" + productCodes;

    try {
        let data = await $.ajax({
            type: 'GET',
            url: url,
        });

        data.forEach(item => {
            let encodedProductCode = getEncodedProductCode(item.code);
            let $target = $(".product-carousel-stock-" + encodedProductCode);
            let $availabilityDiv = $target.addClass(item.statusAvailability);
            let stockIndicator = item.stockIndicator;
            //set info for stock color
            $target.attr('data-stock', stockIndicator);
            $target.attr('data-dealer-stock-quantity', item.dealerStockQuantity);
            $target.attr('data-has-stock-for-dealer', item.hasStockForDealer);
            $target.attr('data-is-subownership', item.subOwnershipStockAvailable);
            let $gtm = $($target.parents().eq(2)).find('[onclick*="selectItemDataLayer"]');
            if ($gtm.length) {
                let onclickVal = $gtm.attr('onclick');

                let updatedOnclick = onclickVal.replace(
                    /(selectItemDataLayer\s*\([^,]+,[^,]+,[^,]+,)[^,]+(,.*\))/,
                    `$1'${item.stockIndicator}'$2`
                );

                $gtm.attr('onclick', updatedOnclick);
            }


            $availabilityDiv.find(".product-carousel-stock-icon-" + encodedProductCode)
                .addClass("fa-solid fa-circle " + item.statusAvailability);

            $target.find(".product-carousel-stock-label-" + encodedProductCode).text(item.statusAvailabilityLabel);
        });
    } catch (err) {
        console.error(err);
    }
}


async function loadPriceAndButton()
{
    let carousels = Array.from($('.js-product-carousel'));
    for (const el of carousels) {
        let $carousel = $(el);
        let href = $carousel.data('href');
        let lastItem = href.split('/').filter(part => part !== '').pop();
        let productCode = lastItem;
        let $stockContainer = $carousel
                .parents()
                .eq(2) // go up 3 levels
                .find('.js-product-carousel-stock');

        let pCode = $stockContainer.data('productcode');
        let stockLevelIndicator = $stockContainer.data('stock');
        let cspsAvailable = $stockContainer.data('has-stock-for-dealer');
        let cspsStock = $stockContainer.data('dealer-stock-quantity');
        let isSubOwnership = $stockContainer.data('is-subownership');
        let url = getCurrentBaseUrl() + 'async/product-carousel/button/' + productCode + "?stock=" + stockLevelIndicator;
        try{
            let data = await $.ajax({
                type: 'GET',
                url: url,
                dataType: 'html',
            });

            let $priceContainer = $(data).filter('.js-product-carousel-price-container');
            let $priceInput = $(data).find('.js-carousel-item-product-price');
            let priceValue = $priceInput.val();

            let $priceTarget = $carousel.closest('a').find('[data-product-price]').first();
            if ($priceTarget.length) {
                $priceTarget.attr('data-product-price', priceValue);
            }

            let $container = $carousel.closest('.card-info-detail-container');
            let $target = $container.closest('[onclick*="selectItemDataLayer"]');

            if ($target.length) {
                let onclickVal = $target.attr('onclick');

                // replace 3rd argument
                let updatedOnclick = onclickVal.replace(
                    /(selectItemDataLayer\s*\([^,]+,[^,]+,)[^,]+(,.*)/,
                    `$1'${priceValue}'$2`
                );

                $target.attr('onclick', updatedOnclick);
            }

            const priceBadgeValue = $priceContainer.find('.js-carousel-item-price-badge-description').val();
            const stockIndicator = $container.find('.js-product-carousel-stock').data('stock');

            $carousel.attr('data-stock', stockIndicator);

            if (priceBadgeValue) {
                const $imageContainer = $target.find('.card-info-detail-body .card-info-detail-image');
                const isRedStock = stockIndicator === 'red';

                var priceBadgeHTML =
                    '<div data-env="desktop" class="tag-discount d-none ' + (isRedStock ? '' : 'd-lg-block') + '">' +
                        priceBadgeValue +
                    '</div>' +
                    '<div data-env="mobile" class="tag-discount mt-2 d-lg-none ' + (isRedStock ? 'd-none' : '') + '">' +
                        priceBadgeValue +
                    '</div>';

                $imageContainer.append(priceBadgeHTML);
            }

            if (stockIndicator === 'red') {
                $priceContainer.addClass('d-none');
            }
            let $oldPriceContainer = $carousel.find('.js-product-carousel-price-container');
            $oldPriceContainer.replaceWith($priceContainer);


            let $targetBtn = $carousel.parent().parent().find('.js-custom-add-to-cart').first();

            if ($targetBtn.length) {
                let $dataContent = $(data).filter('.js-custom-add-to-cart').first();
                let $targetInfo = $dataContent.find('.custom-add-to-cart-'+ getEncodedProductCode(pCode));

                if ($targetInfo.length)
                {
                    $targetInfo.attr({
                        "data-dealer-stock-quantity": cspsStock,
                        "data-has-stock-for-dealer": cspsAvailable,
                        "data-is-subownership": isSubOwnership

                    });
                }

                $targetBtn.replaceWith($dataContent);

            } else {
                console.warn('No .js-custom-add-to-cart found for', productCode);
            }
        }catch(err){
            console.log(err)
        }
    }

}

async function loadGtmCarousel()
{
    let gtmCarousels = Array.from($('.gtmProductCarouselPlaceHolder'));

    for (const el of gtmCarousels) {
        let $gtmCarousel = $(el);
        let itemListName = $gtmCarousel.data('itemlistname');

        // Scope product codes to THIS carousel only by looking at the immediately
        // preceding section. This prevents cross-carousel contamination when
        // multiple carousels are on the same page (which caused 4 view_item_list
        // events instead of 2, and wrong item_list_id/name on add_to_cart).
        let $carouselSection = $gtmCarousel.prev();
        let productCodes = $carouselSection.find('.js-product-carousel')
            .map(function () {
                let href = $(this).data('href');
                return href ? href.split('/').filter(Boolean).pop() : null;
            })
            .get()
            .filter(Boolean);

        if (productCodes.length > 0) {
            let url = getCurrentBaseUrl() + 'async/product-carousel/analytics?productCodes='+productCodes.join(',');
            try {
                let data = await $.ajax({
                    type: 'GET',
                    url: url,
                    dataType: 'json',
                    data: {
                        itemListName: itemListName,
                    },
                });

                if (typeof window.fireViewItemListCarousel === 'function') {
                    window.fireViewItemListCarousel(data);
                }

            } catch (err) {
                console.error('Failed to load carousel analytics.', err);
            }
        }
    }
    console.log('All carousels loaded sequentially!');
}


