$('#fileUploadMethod').on('submit', async function(e) {
    e.preventDefault();

    const form = this;
    const formData = new FormData(form);

    const validateUrl = getCurrentBaseUrl() + 'personalarea/uploadtaxexempt/validate';
    const uploadUrl   = getCurrentBaseUrl() + 'personalarea/uploadtaxexempt';

    try {
        const response = await fetch(validateUrl, {
            method: 'POST',
            body: formData
        });
        const data = await response.json();

        if (data.status === "error") {
            $('#taxExemptFileError').text(data.errors.attachment);
            $('#tax-exemption__upload-btn').text("REPLACE FILE");
            return;
        }

        if (data.status === "success") {
            this.submit();
            location.reload();
        }

        const uploadResponse = await fetch(uploadUrl, {
            method: 'POST',
            body: formData
        });

        if (uploadResponse.ok) {
            location.reload();
        } else {
            $('#taxExemptFileError').text("Upload failed. Please try again.");
        }

    } catch (err) {
        console.error("Validation or upload request failed", err);
        $('#taxExemptFileError').text("Unexpected error occurred.");
    }
});


$('#checkout-summary-tax-upload').on('submit', async function(e) {
    e.preventDefault();

    const formData = new FormData(this);

    const validateUrl = getCurrentBaseUrl() + 'checkout/multi/dealer/checkouttaxupload/validate';
    const uploadUrl   = getCurrentBaseUrl() + 'checkout/multi/dealer/checkouttaxupload';

    try {
        showOverlay();
        console.log("[Checkout] Starting validation request:", validateUrl);
        const response = await fetch(validateUrl, { method: 'POST', body: formData });
        const data = await response.json();
        console.log("[Checkout] Validation response JSON:", data);

        if (data.status === "error") {
            const errorMsg = data.errors?.attachment || $('#taxUploadFileRequired').val();
            console.log("[Checkout] Validation failed. Showing error:", errorMsg);
            $('#taxUploadError').text(errorMsg);
            $('#upload-file__upload-btn').text("REPLACE FILE");
            return;
        }

        if (data.status === "success") {
            console.log("[Checkout] Validation passed. Proceeding to upload:", uploadUrl);
        } else {
            console.warn("[Checkout] Unexpected validation status:", data.status);
            return;
        }

        const uploadResponse = await fetch(uploadUrl, { method: 'POST', body: formData });
        console.log("[Checkout] Upload response status:", uploadResponse.status);

        if (uploadResponse.ok) {
            console.log("[Checkout] Upload succeeded. Reloading page.");
            location.reload();
        } else {
            let errorMsg;
            try {
                const errorData = await uploadResponse.json();
                console.log("[Checkout] Upload error JSON:", errorData);
                errorMsg = errorData.message || $('#taxUploadErrorMsg').val();
            } catch (parseErr) {
                console.warn("[Checkout] Could not parse upload error JSON. Using fallback.", parseErr);
                errorMsg = $('#taxUploadErrorMsg').val();
            }
            console.log("[Checkout] Upload failed. Showing error:", errorMsg);
            $('#taxUploadError').text(errorMsg);
            $('#upload-file__upload-btn').text("REPLACE FILE");
        }

    } catch (err) {
        console.error("[Checkout] Validation or upload request failed:", err);
        $('#taxUploadError').text("Unexpected error occurred.");
        $('#upload-file__upload-btn').text("REPLACE FILE");
    } finally {
        removeOverlay();
        enableCheckoutButtons();
    }
});

