$(document).on('change', '.js-labour-request-checkbox', function() {
    var $checkbox = $(this);
    var labourStatus = $checkbox.is(':checked');
    var isCartPage = $('.checkout-resume').length === 0;

    $checkbox.prop('disabled', true);
    $('#spinner').modal('show');


    $.ajax({
       type: 'POST',
       url: getCurrentBaseUrl() + 'cart/quoteLabour/update',
       contentType: 'application/json',
       data: JSON.stringify({ labourStatus: labourStatus }),
       success: function() {
           if (isCartPage) {
               window.location.reload();
               return;
           }
           var currentPageUrl = window.location.href;
           $.ajax({
               type: 'GET',
               url: currentPageUrl,
               success: function(data) {
                   var checkoutResumeHTML = $(data).find('.checkout-resume')[0];
                   if (checkoutResumeHTML) {
                       $('.checkout-resume').replaceWith(checkoutResumeHTML);
                   }
                   $('#spinner').modal('hide');
                   $checkbox.prop('disabled', false);
               },
               error: function(err) {
                   console.log(err);
                   $('#spinner').modal('hide');
                   $checkbox.prop('disabled', false);
               }
           });
       },
       error: function(err) {
           console.log(err);
           $('#spinner').modal('hide');
           $checkbox.prop('disabled', false);
       }
    });
});

