function retrieveCsvFile(formId){
    var fileName = $('.cnhi-search-in-model-search-button.active').attr('data-csv-file-name');
    var jsonList = JSON.stringify(searchInModelObject.getResults());

    spinnerLoad.addSpinner("retrieveCsvFile");
    $("#fileName").val(fileName);
    $("#jsonList").val(jsonList);

    if ($('#cnhi-expand-models').hasClass('disabled') && $('#cnhi-expand-brands').hasClass('disabled')) {
    	$("#searchType").val('All Brands');
    } else if ($('#cnhi-expand-models').hasClass('disabled') && !$('#cnhi-expand-brands').hasClass('disabled')) {
    	$("#searchType").val('All Models');
    } else {
    	$("#searchType").val('Selected Model');
    }

    $("#"+formId).submit();
    spinnerLoad.removeSpinnerOnSuccess("retrieveCsvFile");

}

var isAssemblyPage;
var assemblyModelId;
var myEquipmentModelNumber;

$(document).ready(function () {
    $('#partium-fail-scenario-modal').appendTo('body');
    $('#partium-refine-your-search-modal').appendTo('body');

    //DESKTOP EVENTS
    $("#partium-img-search-btn, #change-image-btn-plp-partium-js").on('click',function () {
        isAssemblyPage = null;
        assemblyModelId = null;

        let myEquipmentModelNumberStored = sessionStorage.getItem('myEquipmentModelNumberStored');
        sessionStorage.removeItem('myEquipmentModelNumberStored');

        myEquipmentModelNumber = myEquipmentModelNumberStored;
        showImageSearch();
    });

    $(document).on('click', '#partium-img-search-btn-equipment', function () {
        isAssemblyPage = null;
        assemblyModelId = null;

        let modelNumber = $(this).data('model-number');
        let myEquipmentModelNumberStored = modelNumber ? modelNumber.toString().trim() : null;
        sessionStorage.setItem('myEquipmentModelNumberStored', myEquipmentModelNumberStored);

        $("#partium-img-search-btn").trigger('click');
    });

    $("#partium-img-search-btn-assembly").on('click',function () {
        isAssemblyPage = $(this).data('assembly-page');
        assemblyModelId = $('#assemblyModelId').data('model-id');
        myEquipmentModelNumber = null;
        showImageSearch();
    })

    $("#partium-input-placeholder").on('change',function () {
        addSpinnerPartium('.camera-container');
        callPartiumSearchByImage();
    });

    //MOBILE EVENTS
    $("#partium-input-placeholder-mobile").on('change',function () {
        addSpinnerPartium('.camera-container-mobile');
        callPartiumSearchByImageMobile();
    });

    $("#try-again-btn-js").on('click',function () {
        const deviceEnv = getDeviceEnv();
        $('#partium-fail-scenario-modal').modal('hide');
        removeSpinner();
        showImageSearch();

        if (deviceEnv == 'Mobile' || deviceEnv == 'Tablet') {
            $('#cameraFileInputMobile').click();
        }
    });

    //refine
    $("#refine-your-search-btn").on('click',function () {
        const deviceEnv = getDeviceEnv();
        removeSpinner();
        if (deviceEnv == 'Mobile' || deviceEnv == 'Tablet') {
            populateCommercialModelListMobile();
            showModal('#partium-image-search-mobile-modal');
        } else {
            populateCommercialModelList();
            showModal('#image-search-camera-modal');
        }
    });

    $("#continuar-btn").on('click',function () {
        if(sessionStorage.getItem("partiumSessionId")) {
            redirectToPlp(sessionStorage.getItem("partiumSessionId"), "");
            sessionStorage.removeItem("partiumSessionId");
        }
    });
	
	$('#partiumSelectSavedEquipmentImgSearchDesktop').on('change', function() {
		const selectedValue = this.value;
		const selectedText = this.options[this.selectedIndex].text;

		if (selectedValue === 'savedEquipOptSearchModel') {
			populateCommercialModelList();
		} else {
			populateSavedModelList();
		}
	});

	$('#partiumSelectSavedEquipmentImgSearchMobile').on('change', function() {
		const selectedValue = this.value;
		const selectedText = this.options[this.selectedIndex].text;

		if (selectedValue === 'savedEquipOptSearchModel') {
			populateCommercialModelListMobile();
		} else {
			populateSavedModelListMobile();
		}
	});

});

function addSpinnerPartium(element) {
  const spinner = $('<div class="loader custom-spinner"></div>').css({
      position: 'absolute',
      placeSelf: 'anchor-center',
      transform: 'translate(-50%, -50%)',
      zIndex: 1050
  });

  $(element).append(spinner);
}

function removeSpinner() {
    $(".custom-spinner").remove();
}

function showImageSearch() {
	var anonymous = $(".log").attr('data-anonymous');
	const equipmentCount = $('.icon-my-equipment__number').text();
	const deviceEnv = getDeviceEnv();
    if (deviceEnv == 'Mobile' || deviceEnv == 'Tablet') {
		if (myEquipmentModelNumber) {
            $('#partiumSelectSavedEquipmentImgSearchMobile').val('savedEquipOptSearchModel').trigger('change');
        }
		else if (anonymous === 'true' || equipmentCount < 1) {
        	populateCommercialModelListMobile();
		}
		else {
		    if(isAssemblyPage !== 'undefined' && isAssemblyPage == 'assembly')
            {
                $("#partiumSelectSavedEquipmentImgSearchMobile").prop("selectedIndex", 1).trigger("change");
            }
            else
            {
			    populateSavedModelListMobile();
			}
		}
        resetCameraModalMobile();
        showModal('#partium-image-search-mobile-modal');
    } else {
        if (myEquipmentModelNumber) {
            $('#partiumSelectSavedEquipmentImgSearchDesktop').val('savedEquipOptSearchModel').trigger('change');
        }
		else if (anonymous === 'true' || equipmentCount < 1) {
			populateCommercialModelList();
		}
		else {
		    if(isAssemblyPage !== 'undefined' && isAssemblyPage == 'assembly')
		    {
                $("#partiumSelectSavedEquipmentImgSearchDesktop").prop("selectedIndex", 1).trigger("change");
            }
            else
            {
                populateSavedModelList();
            }
		}
        resetCameraModal();
        showModal('#image-search-camera-modal');
    }
}

function showModal(selector) {
    $(selector).modal({
        show: true,
        backdrop: 'static',
        keyboard: false
    });
};


function setCommercialModelPlaceholder() {
    const placeholderLabel = $('#partium-com-model-select-desktop').data('placeholder-label');
    $('#partium-com-model-select-desktop').select2({
      dropdownParent: $("#image-search-camera-modal"),
      templateSelection: function templateSelection(data) {
        if (data.id == '') {
          return $('<span>' + placeholderLabel.split("-")[0] + ' - ' + placeholderLabel.split("-")[1] + '</span>');
        }
        return data.text;
      }
    });
}

function setCommercialModelPlaceholderMobile() {
    const placeholderLabel = $('#partium-com-model-select-mobile').data('placeholder-label');
    $('#partium-com-model-select-mobile').select2({
      dropdownParent: $("#partium-image-search-mobile-modal"),
      templateSelection: function templateSelection(data) {
        if (data.id == '') {
          return $('<span>' + placeholderLabel.split("-")[0] + ' - ' + placeholderLabel.split("-")[1] + '</span>');
        }
        return data.text;
      }
    });
}

function callPartiumSearchByImage() {
    var croppedImage = document.getElementById("croppedImage");
    var imageData = croppedImage.src.split(",")[1];
    var partiumResultsThreshold = parseInt($('.js-partium-results-threshold').attr('data-partium-results-threshold'));

    var fd = new FormData();
    var modelNumber = $('#partium-com-model-select-desktop').val();

    if (modelNumber == undefined) {
        modelNumber = "";
    }

    fd.append('imageData', imageData);
    fd.append('modelNumber', modelNumber);
    var baseUrl = getCurrentBaseUrl();

    $.ajax({
        url: baseUrl + 'partium/uploadPartiumImage',
        type: 'POST',
        data: fd,
        contentType: false,
        processData: false,
        success: function(data) {
            if (data.resultsTotalCount == 0 || data == "") {
                document.activeElement.blur();
                $('#image-search-camera-modal').modal('hide');
                showModal('#partium-fail-scenario-modal');
            } else if (data.resultsTotalCount > partiumResultsThreshold) {
                if (modelNumber == "") {
                    document.activeElement.blur();
                    sessionStorage.setItem("partiumSessionId",data.sessionId);
                    $('#image-search-camera-modal').modal('hide');
                    showModal('#partium-refine-your-search-modal');
                } else {
                    document.activeElement.blur();
                     redirectToPlp(data.sessionId, modelNumber);
                }
            } else {
                redirectToPlp(data.sessionId, modelNumber);
            }
        },
        error: function(error) {
            removeSpinner();
            console.log("fail");
        }
    });
}

function callPartiumSearchByImageMobile() {
    var croppedImage = document.getElementById("croppedImageMobile");
    var imageData = croppedImage.src.split(",")[1];
    var partiumResultsThreshold = parseInt($('.js-partium-results-threshold').attr('data-partium-results-threshold'));

    var fd = new FormData();
    var modelNumber = $('#partium-com-model-select-mobile').val();

    if (modelNumber == undefined) {
        modelNumber = "";
    }

    fd.append('imageData', imageData);
    fd.append('modelNumber', modelNumber);
    var baseUrl = getCurrentBaseUrl();

    console.log("imageData: "+imageData)

    $.ajax({
        url: baseUrl + 'partium/uploadPartiumImage',
        type: 'POST',
        data: fd,
        contentType: false,
        processData: false,
        success: function(data) {
            if (data.resultsTotalCount == 0 || data == "") {
                document.activeElement.blur();
                $('#partium-image-search-mobile-modal').modal('hide');
                showModal('#partium-fail-scenario-modal');
            } else if (data.resultsTotalCount > partiumResultsThreshold) {
                if (modelNumber == "") {
                    document.activeElement.blur();
                    sessionStorage.setItem("partiumSessionId", data.sessionId);
                    $('#partium-image-search-mobile-modal').modal('hide');
                    showModal('#partium-refine-your-search-modal');
                } else {
                     redirectToPlp(data.sessionId, modelNumber);
                }
            } else {
                redirectToPlp(data.sessionId, modelNumber);
            }
        },
        error: function(error) {
            removeSpinner();
            console.log("fail");
        }
    });
}

function redirectToPlp(sessionId, modelNumber) {
     var searchParams = "search/?text=partium&isPartium=true";

     if (sessionId) {
        searchParams = searchParams.concat("&psid=" + sessionId);
     }
     if (modelNumber) {
        searchParams = searchParams.concat("&pcm=" + encodeURIComponent(modelNumber));
     }
     window.location.href = getCurrentBaseUrl() + searchParams;
}

function populateCommercialModelList() {
    var baseUrl = getCurrentBaseUrl();
    var commercialModelDropdown = document.getElementById("partium-com-model-select-desktop");
    var options = [];
    var option = document.createElement("option");
    commercialModelDropdown.options.length = 1;

    setCommercialModelPlaceholder();

    $.ajax({
        type: 'GET',
        url: baseUrl + 'cn/partium/populateCommercialModelDropdown',

        success: function(data) {
            option.text = "N/A";
            option.value = "";
            options.push(option.outerHTML);

            for (var i = 0; i < data.length; i++) {
                option.text = data[i];
                option.value = data[i];
                options.push(option.outerHTML);
            }
            if (data.length == 0) {
                commercialModelDropdown.setAttribute('disabled','');
            } else {
                commercialModelDropdown.removeAttribute('disabled');
            }

            commercialModelDropdown.insertAdjacentHTML('beforeEnd', options.join('\n'));
            selectModelCodeInDropDown(commercialModelDropdown);
        },
        error: function(error) {
            console.log("fail");
        }
    });
}

