$('.save-button-loyalty-program').on('click', function(e) {
	addSpinner("#loyalty-program-tandc-continue-btn-js", "top-20");
    e.preventDefault();
    var validationError = false

    $("form[id*=address-info-loyalty-program-form] :visible :input").each(function(){
        if ($(this).next('.form-bg-error').length) {
            $(this).next('.form-bg-error').remove();
            $(this).next('[data-error-field="true"]').remove();
        }

        if($(this).data('mandatory') == true &&  $(this).val() == ""){
            validationError = true;
            $(this).after('<div class="form-bg-error" style="content: &quot;&quot;; position: absolute; bottom: 1px; top: 25px; left: 15px;"></div><small data-error-field="true" class="text-danger">' + $(this).data('msg-required') + '</small>');
            removeSpinner();
        }

        if($(this).attr("id") == "address.postcode" && $(this).val().length < 5){
            validationError = true;
            $(this).after('<div class="form-bg-error" style="content: &quot;&quot;; position: absolute; bottom: 1px; top: 25px; left: 15px;"></div><small data-error-field="true" class="text-danger">' + $(this).data('msg-required') + '</small>');
        }

    });


    if ($("#add-state-loyalty-program").length != 0) {
        $("#add-state-loyalty-program").next('.form-bg-error').remove();
        $("#add-state-loyalty-program").next('[data-error-field="true"]').remove();

        if($("#add-state-loyalty-program").val() == "" || $("#add-state-loyalty-program").val() == null){
            validationError = true;
            $("#add-state-loyalty-program").after('<div class="form-bg-error" style="content: &quot;&quot;; position: absolute; bottom: 1px; top: auto; left: 1px;"></div><small data-error-field="true" class="text-danger">' + $("#add-state-loyalty-program").data('msg-required') + '</small>');
        }
    }

    if ($("#add-country-loyalty-program").length != 0) {
        $("#add-country-loyalty-program").next('.form-bg-error').remove();
        $("#add-country-loyalty-program").next('[data-error-field="true"]').remove();

        if($("#add-country-loyalty-program").val() == "" || $("#add-country-loyalty-program").val() == null){
            validationError = true;
            $("#add-country-loyalty-program").after('<div class="form-bg-error" style="content: &quot;&quot;; position: absolute; bottom: 1px; top: auto; left: 1px;"></div><small data-error-field="true" class="text-danger">' + $("#add-state-loyalty-program").data('msg-required') + '</small>');
        }
    }

    if(!validationError)
    {
        processLoyaltySignUp(e);
    }
});


function processLoyaltySignUpv2(e)
{
    e.preventDefault();
    let baseUrl = getCurrentBaseUrl();
    addSpinner(".main", "top-20")
    let phoneNumber = $('#personal-area-signup-form').find('#phone-number-loyalty-program').val();
    $.ajax({
        url:baseUrl+'/loyalty-program-enrollment/signUp?phoneNumber=' + phoneNumber,
        type:'post',
        data: $("#personal-area-signup-form").serialize(),
        success:function(data)
        {
           $("#loyalty-enrollment-error").remove();
            let loyaltyErrorMessage = $(data.loyaltyProgramErrorMessageModal).data('loyalty-message');
            if(loyaltyErrorMessage != null && loyaltyErrorMessage != '')
            {
                $('.loyalty-error').text(loyaltyErrorMessage).show();
                 removeSpinner();
            }
            else
            {
                removeFirstLoginLoyalty();
                removeSpinner();
                $("#loyalty-program-success-modal").modal('show');

                var $closeBtn = $("#loyalty-program-signup-complete-close-btn-js");
                $closeBtn.off("click").on("click", function () {
                    $("#loyalty-program-success-modal").modal("hide");
                });
            }
        },
        error: function(e)
        {
            removeSpinner();
            console.log(e);
        }
    });
}


