function processLoyaltySignUp(e)
{
    var baseUrl = getCurrentBaseUrl();
    var phoneNumber = $('#phone-number-info-loyalty-program-form').find('#phone-number-loyalty-program').val()
    $.ajax({
        url:baseUrl+'/loyalty-program-enrollment/signUp?phoneNumber=' + phoneNumber,
        type:'post',
        data:$('#address-info-loyalty-program-form').serialize(),
        success:function(data)
        {
           $("#loyalty-enrollment-error").remove();
            var loyaltyErrorMessage = $(data.loyaltyProgramErrorMessageModal).data('loyalty-message');
            if(loyaltyErrorMessage != null && loyaltyErrorMessage != '')
            {
                if(loyaltyErrorMessage.includes("LoyaltyAddressError"))
                {
                   var addressErrorMessage = loyaltyErrorMessage.replace("LoyaltyAddressError:", "");
                    $("#address-info-loyalty-program-form").find(".loyalty-display-error-message").after('<small id="loyalty-enrollment-error" data-error-field="true" class="text-danger ">' + addressErrorMessage + '</small>');
                    $("#address-info-collapse").addClass('show');
                    $("#loyalty-program-tandc-info-collapse").removeClass('show');
                }
                else
                {
                    $("#phone-number-info-loyalty-program-form").find(".loyalty-display-error-message").after('<small id="loyalty-enrollment-error" data-error-field="true" class="text-danger ">' + loyaltyErrorMessage + '</small>');
                    $("#phone-number-info-collapse").addClass('show');
                    $("#loyalty-program-tandc-info-collapse").removeClass('show');
                }
            }
            else
            {
                removeFirstLoginLoyalty();
                $("#cnh-loyalty-program-enrollment-modal").modal('hide');
                removeSpinner();
                $("#loyalty-program-success-modal").modal('show');
            }
            removeSpinner();
        },
        error: function(e)
        {
            removeSpinner();
            console.log(e);
        }
    });
}

